// Procedural vector fighter rig + animation clips
const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (t) => t * t * (3 - 2 * t);
const easeOut = (t) => 1 - (1 - t) * (1 - t);
const dir = (a) => ({ x: Math.sin(a), y: Math.cos(a) });

const BASE = {
