      { t: 0.75, p: { dy: -6, lean: 0.06, fThigh: -0.12, fShin: 0.04, bThigh: 0.16, bShin: 0.06, fUp: 0.03, fFore: 0.02, bUp: 0.04, bFore: 0.05 } },
