// Arena, camera, effects and projectile rendering
import { ARENAS, FIGHTERS, WORLD } from './data.js';
import { drawFighter, drawShadow } from './rig.js';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = mulberry32(0xb1ade);
const buildingsFar = [];
const buildingsMid = [];
const stars = [];
const rain = [];
const snow = [];
const embers = [];
const dust = [];
for (let i = 0; i < 140; i++) stars.push({ x: rng(), y: rng() * 0.62, s: rng() * 1.8 + 0.4, p: rng() * TAU });
for (let x = -260; x < 2200; x += 58 + rng() * 100) {
  buildingsFar.push({ x, w: 50 + rng() * 110, h: 70 + rng() * 250, c: rng(), s: rng() });
}
for (let x = -240; x < 2200; x += 90 + rng() * 130) {
  buildingsMid.push({ x, w: 60 + rng() * 120, h: 110 + rng() * 330, c: rng(), s: rng() });
}
for (let i = 0; i < 120; i++) rain.push({ x: rng(), y: rng(), len: 8 + rng() * 20, sp: 0.5 + rng() * 1.1, a: 0.04 + rng() * 0.14 });
for (let i = 0; i < 150; i++) snow.push({ x: rng(), y: rng(), r: 0.6 + rng() * 2.4, sp: 0.02 + rng() * 0.08, sway: rng() * TAU, a: 0.18 + rng() * 0.55 });
for (let i = 0; i < 90; i++) embers.push({ x: rng(), y: rng(), r: 0.6 + rng() * 2.4, sp: 0.01 + rng() * 0.06, sway: rng() * TAU, a: 0.2 + rng() * 0.7 });
for (let i = 0; i < 45; i++) dust.push({ x: rng(), y: rng(), r: 0.5 + rng() * 2.2, sp: 0.005 + rng() * 0.02, sway: rng() * TAU, a: 0.08 + rng() * 0.2 });

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.w = 0;
    this.h = 0;
    this.dpr = 1;
    this.view = null;
    this.camera = { x: 800, span: 520, smoothX: 800, smoothSpan: 520 };
    this.resize();
  }

  resize() {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    this.dpr = dpr;
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.canvas.width = Math.floor(this.w * dpr);
    this.canvas.height = Math.floor(this.h * dpr);
    this.canvas.style.width = this.w + 'px';
    this.canvas.style.height = this.h + 'px';
  }

  setTarget(x, span) {
    this.camera.x = x;
    this.camera.span = span;
  }

  computeView(dt = 1 / 60) {
    const w = this.w, h = this.h;
    const aspect = w / h;
    const mobile = w < 860 && aspect < 1.02;
    const cam = this.camera;
    cam.smoothX += (cam.x - cam.smoothX) * Math.min(1, dt * 8);
    cam.smoothSpan += (cam.span - cam.smoothSpan) * Math.min(1, dt * 5);
    let scale, offX, offY, camX;
    if (mobile) {
      const desired = clamp(cam.smoothSpan + 265, 660, 1360);
      scale = clamp(w / desired, 0.33, 0.72);
      camX = clamp(cam.smoothX, desired / 2, WORLD.w - desired / 2);
      offX = w / 2 - camX * scale;
      offY = h * 0.625 - WORLD.ground * scale;
    } else {
      scale = Math.max(w / WORLD.w, h / WORLD.h);
      camX = 800;
      offX = w / 2 - 800 * scale;
      offY = h / 2 - 450 * scale;
    }
    this.view = {
      w, h, scale, offX, offY, camX, mobile,
      groundY: offY + WORLD.ground * scale,
      horizon: offY + 548 * scale,
      visibleW: w / scale,
      visibleH: h / scale,
    };
    return this.view;
  }

  render(scene, dt) {
    const ctx = this.ctx;
    const v = this.computeView(dt);
    const dpr = this.dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    const arena = ARENAS[scene.arena] || ARENAS[0];
    this.drawArena(ctx, arena, scene.time, v);
    this.drawArenaParticles(ctx, arena, scene.time, v);

    const shake = scene.shake || 0;
    const sx = shake ? Math.sin(scene.time * 71) * shake : 0;
    const sy = shake ? Math.cos(scene.time * 83) * shake * 0.6 : 0;

    ctx.save();
    ctx.translate(v.offX + sx, v.offY + sy);
    ctx.scale(v.scale, v.scale);

    const fighters = scene.fighters || [];
    // accent glow under each fighter
    for (const f of fighters) {
      if (!f) continue;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(f.x, WORLD.ground - 2, 3, f.x, WORLD.ground - 2, 100);
      g.addColorStop(0, f.def.accent + '22');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(f.x, WORLD.ground, 110, 20, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
      drawShadow(ctx, f, scene.time);
    }

    // ground dust / low particles behind fighters
    this.drawParticles(ctx, (scene.particles || []).filter((p) => p.layer === 'back'), scene.time);

    const order = fighters.filter(Boolean).slice().sort((a, b) => {
      const aa = a.state === 'attack' ? 1 : 0;
      const bb = b.state === 'attack' ? 1 : 0;
      if (aa !== bb) return aa - bb;
      return a.x - b.x;
    });
    for (const f of order) drawFighter(ctx, f, scene.time, { koTime: f.state === 'ko' ? f.koTime : 0 });

    this.drawProjectiles(ctx, scene.projectiles || [], scene.time);
    this.drawParticles(ctx, (scene.particles || []).filter((p) => p.layer !== 'back'), scene.time);
    this.drawEffects(ctx, scene.effects || [], scene.time);

    ctx.restore();

    // foreground atmosphere
    this.drawForeground(ctx, arena, scene.time, v, scene);
    if (scene.flash > 0) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = Math.min(0.6, scene.flash);
      ctx.fillStyle = '#dff8ff';
      ctx.fillRect(0, 0, this.w, this.h);
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';
    }
  }

  drawArena(ctx, arena, t, v) {
    const { w, h } = v;
    const gY = v.groundY;
    const sky = ctx.createLinearGradient(0, 0, 0, Math.max(v.horizon, gY));
    sky.addColorStop(0, arena.sky[0]);
    sky.addColorStop(0.45, arena.sky[1]);
    sky.addColorStop(0.8, arena.sky[2]);
    sky.addColorStop(1, arena.sky[3]);
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    if (arena.key === 'neon') this.drawNeon(ctx, t, v);
    else if (arena.key === 'frost') this.drawFrost(ctx, t, v);
    else this.drawFoundry(ctx, t, v);

    // global haze at the horizon
    const fog = ctx.createLinearGradient(0, v.horizon - 160 * v.scale, 0, gY + 40);
    fog.addColorStop(0, 'rgba(0,0,0,0)');
    fog.addColorStop(0.65, arena.fog);
    fog.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = fog;
    ctx.fillRect(0, v.horizon - 180 * v.scale, w, gY - v.horizon + 220 * v.scale);
  }

  drawNeon(ctx, t, v) {
    const { w, h } = v;
    const gY = v.groundY;
    const s = v.scale;
    const horizon = v.horizon;

    // stars
    for (const st of stars) {
      const tw = 0.35 + Math.sin(t * 1.4 + st.p) * 0.3;
      ctx.globalAlpha = tw;
      ctx.fillStyle = '#c8e9ff';
      ctx.fillRect(st.x * w, st.y * horizon, st.s, st.s);
    }
    ctx.globalAlpha = 1;

    // moon
    const mx = w * 0.76 - (v.camX - 800) * s * 0.04;
    const my = horizon * 0.34;
    const mr = 64 * s;
    const mg = ctx.createRadialGradient(mx, my, mr * 0.2, mx, my, mr * 3.4);
    mg.addColorStop(0, 'rgba(190, 230, 255, 0.32)');
    mg.addColorStop(0.22, 'rgba(130, 190, 255, 0.13)');
    mg.addColorStop(1, 'rgba(40, 100, 220, 0)');
    ctx.fillStyle = mg;
    ctx.beginPath();
    ctx.arc(mx, my, mr * 3.4, 0, TAU);
    ctx.fill();
    const moonG = ctx.createLinearGradient(mx, my - mr, mx, my + mr);
    moonG.addColorStop(0, '#eaf7ff');
    moonG.addColorStop(0.55, '#b8d9ea');
    moonG.addColorStop(1, '#7c9fbf');
    ctx.fillStyle = moonG;
    ctx.beginPath();
    ctx.arc(mx, my, mr, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(50, 80, 120, 0.18)';
    ctx.beginPath();
    ctx.arc(mx - mr * 0.3, my - mr * 0.15, mr * 0.25, 0, TAU);
    ctx.arc(mx + mr * 0.35, my + mr * 0.2, mr * 0.16, 0, TAU);
    ctx.fill();

    // glow behind skyline
    const bg = ctx.createRadialGradient(w * 0.64, horizon, 10, w * 0.64, horizon, w * 0.7);
    bg.addColorStop(0, 'rgba(255, 38, 130, 0.20)');
    bg.addColorStop(0.35, 'rgba(93, 45, 180, 0.14)');
    bg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    const bx = (x) => v.offX + x * s;

    // far skyline
    for (const b of buildingsFar) {
      const x = bx(b.x);
      const bw = b.w * s;
      const bh = b.h * s;
      if (x + bw < -20 || x > w + 20) continue;
      ctx.fillStyle = b.s > 0.55 ? '#0a1129' : '#0c1430';
      ctx.fillRect(x, horizon - bh, bw, bh + 4 * s);
      ctx.fillStyle = 'rgba(96, 165, 230, 0.20)';
      for (let wy = horizon - bh + 10 * s; wy < horizon - 8 * s; wy += 13 * s) {
        for (let wx = x + 5 * s; wx < x + bw - 5 * s; wx += 11 * s) {
          if (((wx + wy) | 0) % 29 < 16) ctx.fillRect(wx, wy, 3 * s, 4 * s);
        }
      }
    }

    // mid skyline
    for (let i = 0; i < buildingsMid.length; i++) {
      const b = buildingsMid[i];
      const x = bx(b.x);
      const bw = b.w * s;
      const bh = b.h * s;
      if (x + bw < -40 || x > w + 40) continue;
      const grad = ctx.createLinearGradient(x, horizon - bh, x, horizon);
      grad.addColorStop(0, '#111b3f');
      grad.addColorStop(1, '#080d20');
      ctx.fillStyle = grad;
      ctx.fillRect(x, horizon - bh, bw, bh + 3 * s);

      // roof antenna
      if (b.s > 0.66) {
        ctx.strokeStyle = 'rgba(100, 180, 240, 0.3)';
        ctx.lineWidth = 1.5 * s;
        ctx.beginPath();
        ctx.moveTo(x + bw * 0.5, horizon - bh);
        ctx.lineTo(x + bw * 0.5, horizon - bh - 28 * s);
        ctx.stroke();
        ctx.fillStyle = 'rgba(255, 50, 120, 0.9)';
        ctx.beginPath();
        ctx.arc(x + bw * 0.5, horizon - bh - 29 * s, 2.2 * s, 0, TAU);
        ctx.fill();
      }

      // windows
      ctx.fillStyle = 'rgba(255, 186, 92, 0.38)';
      for (let wy = horizon - bh + 16 * s; wy < horizon - 12 * s; wy += 17 * s) {
        for (let wx = x + 7 * s; wx < x + bw - 8 * s; wx += 14 * s) {
          const n = Math.sin(wx * 12.3 + wy * 2.1 + i) * 1000;
          if (n - Math.floor(n) > 0.54) ctx.fillRect(wx, wy, 4.5 * s, 6 * s);
        }
      }
      // neon building edge
      if (i % 3 === 0) {
        ctx.strokeStyle = i % 6 === 0 ? 'rgba(80, 230, 255, 0.5)' : 'rgba(255, 61, 158, 0.45)';
        ctx.lineWidth = 2 * s;
        ctx.beginPath();
        ctx.moveTo(x + bw, horizon - bh + 10 * s);
        ctx.lineTo(x + bw, horizon);
        ctx.stroke();
      }
    }

    // hanging neon signs / billboards
    const signGlow = 0.7 + Math.sin(t * 6.5) * 0.08;
    ctx.save();
    ctx.shadowColor = '#54e6ff';
    ctx.shadowBlur = 24 * s;
    ctx.fillStyle = `rgba(54, 230, 255, ${0.22 * signGlow})`;
    const signX = w * 0.13 - (v.camX - 800) * s * 0.1;
    const signY = horizon * 0.55;
    ctx.fillRect(signX, signY, 38 * s, 120 * s);
    ctx.fillStyle = '#d4fdff';
    ctx.font = `700 ${19 * s}px "Rajdhani", sans-serif`;
    ctx.textAlign = 'center';
    ctx.save();
    ctx.translate(signX + 19 * s, signY + 50 * s);
    ctx.rotate(Math.PI / 2);
    ctx.fillText('BLADE', -32 * s, 6 * s);
    ctx.restore();
    ctx.restore();

    // magenta sign
    ctx.save();
    ctx.shadowColor = '#ff3d9e';
    ctx.shadowBlur = 20 * s;
    ctx.fillStyle = `rgba(255, 61, 158, ${0.26 * (0.75 + Math.sin(t * 3.1 + 2) * 0.1)})`;
    const s2x = w * 0.88 - (v.camX - 800) * s * 0.12;
    ctx.fillRect(s2x, horizon * 0.48, 26 * s, 88 * s);
    ctx.fillStyle = '#ffe0f1';
    ctx.font = `700 ${15 * s}px "Rajdhani", sans-serif`;
    ctx.fillText('09', s2x + 13 * s, horizon * 0.48 + 46 * s);
    ctx.restore();

    // rooftop floor
    const floor = ctx.createLinearGradient(0, gY, 0, h);
    floor.addColorStop(0, '#0c1126');
    floor.addColorStop(0.35, '#080b1a');
    floor.addColorStop(1, '#03040b');
    ctx.fillStyle = floor;
    ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);

    // glowing edge
    ctx.save();
    ctx.shadowColor = '#50e6ff';
    ctx.shadowBlur = 18 * s;
    ctx.strokeStyle = 'rgba(96, 234, 255, 0.9)';
    ctx.lineWidth = 2.5 * s;
    ctx.beginPath();
    ctx.moveTo(0, gY);
    ctx.lineTo(w, gY);
    ctx.stroke();
    ctx.restore();

    // floor perspective grid
    ctx.strokeStyle = 'rgba(70, 155, 220, 0.12)';
    ctx.lineWidth = 1;
    const vanish = w / 2 - (v.camX - 800) * s * 0.18;
    for (let i = 0; i < 12; i++) {
      const k = i / 12;
      const y = gY + Math.pow(k, 1.7) * (h - gY);
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    for (let i = -9; i <= 9; i++) {
      ctx.beginPath();
      ctx.moveTo(vanish + i * 90 * s, gY);
      ctx.lineTo(vanish + i * 330 * s, h);
      ctx.stroke();
    }

    // magenta reflection streaks
    for (let i = 0; i < 5; i++) {
      const x = ((i * 0.23 + 0.08) * w + Math.sin(t * 0.2 + i) * 20 * s) - (v.camX - 800) * s * 0.25;
      const g = ctx.createLinearGradient(x, gY, x, h);
      g.addColorStop(0, 'rgba(255, 61, 158, 0.13)');
      g.addColorStop(0.6, 'rgba(255, 61, 158, 0.02)');
      g.addColorStop(1, 'rgba(255, 61, 158, 0)');
      ctx.fillStyle = g;
      ctx.fillRect(x, gY, 34 * s, h - gY);
    }

    // distant rooftop clutter
    this.rooftopUnits(ctx, v, t);
  }

  rooftopUnits(ctx, v, t) {
    const s = v.scale, gY = v.groundY;
    const units = [
      { x: 0.06, w: 90, h: 45, glow: '#38cfe8' },
      { x: 0.91, w: 120, h: 58, glow: '#ff3d9e' },
    ];
    for (const u of units) {
      const x = u.x * v.w - (v.camX - 800) * s * 0.3;
      const w = u.w * s, h = u.h * s;
      ctx.fillStyle = '#0b1329';
      ctx.fillRect(x, gY - h, w, h);
      ctx.strokeStyle = 'rgba(90, 180, 230, 0.25)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x, gY - h, w, h);
      ctx.fillStyle = 'rgba(80, 200, 235, 0.35)';
      ctx.fillRect(x + 6 * s, gY - h + 7 * s, w - 12 * s, 2 * s);
      ctx.fillStyle = u.glow;
      ctx.globalAlpha = 0.45 + Math.sin(t * 4 + x) * 0.15;
      ctx.fillRect(x + w * 0.7, gY - h + 12 * s, 3 * s, 3 * s);
      ctx.globalAlpha = 1;
    }
  }

  drawFrost(ctx, t, v) {
    const { w, h } = v;
    const gY = v.groundY;
    const s = v.scale;
    const horizon = v.horizon;

    for (const st of stars) {
      const tw = 0.3 + Math.sin(t * 1.1 + st.p) * 0.25;
      ctx.globalAlpha = tw;
      ctx.fillStyle = '#d6f6ff';
      ctx.fillRect(st.x * w, st.y * horizon, st.s, st.s);
    }
    ctx.globalAlpha = 1;

    // aurora ribbons
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 3; i++) {
      const yy = horizon * (0.2 + i * 0.09);
      const g = ctx.createLinearGradient(0, yy, w, yy + 80 * s);
      g.addColorStop(0, 'rgba(70, 255, 210, 0)');
      g.addColorStop(0.35, `rgba(${70 + i * 40}, 255, 210, ${0.08 + i * 0.025})`);
      g.addColorStop(0.6, `rgba(90, 150, 255, ${0.06 + i * 0.02})`);
      g.addColorStop(1, 'rgba(40, 80, 200, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(-40, yy);
      for (let x = -40; x <= w + 40; x += 60) {
        const y = yy + Math.sin(x * 0.006 + t * 0.4 + i * 1.8) * 22 * s + Math.sin(x * 0.013 + i) * 10 * s;
        ctx.lineTo(x, y);
      }
      for (let x = w + 40; x >= -40; x -= 60) {
        const y = yy + 70 * s + Math.sin(x * 0.005 + t * 0.3 + i * 1.2) * 26 * s;
        ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // moon
    const mx = w * 0.73;
    const my = horizon * 0.27;
    const mr = 72 * s;
    const mg = ctx.createRadialGradient(mx, my, mr * 0.2, mx, my, mr * 3);
    mg.addColorStop(0, 'rgba(190, 245, 255, 0.30)');
    mg.addColorStop(0.3, 'rgba(130, 210, 255, 0.1)');
    mg.addColorStop(1, 'rgba(70, 130, 220, 0)');
    ctx.fillStyle = mg;
    ctx.beginPath();
    ctx.arc(mx, my, mr * 3, 0, TAU);
    ctx.fill();
    const moonG = ctx.createLinearGradient(mx, my - mr, mx, my + mr);
    moonG.addColorStop(0, '#ffffff');
    moonG.addColorStop(0.6, '#d9f4ff');
    moonG.addColorStop(1, '#9cc8e0');
    ctx.fillStyle = moonG;
    ctx.beginPath();
    ctx.arc(mx, my, mr, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(120, 160, 190, 0.14)';
    ctx.beginPath();
    ctx.arc(mx - mr * 0.28, my + mr * 0.12, mr * 0.3, 0, TAU);
    ctx.arc(mx + mr * 0.35, my - mr * 0.3, mr * 0.17, 0, TAU);
    ctx.fill();

    // mountain layers
    const mountains = [
      { base: horizon + 12 * s, h: 260, c1: '#091a2d', c2: '#0b2138', snow: 'rgba(160, 220, 245, 0.22)' },
      { base: horizon + 34 * s, h: 190, c1: '#0b2234', c2: '#102c42', snow: 'rgba(180, 235, 255, 0.3)' },
    ];
    for (let m = 0; m < mountains.length; m++) {
      const mt = mountains[m];
      const off = (v.camX - 800) * s * (0.15 + m * 0.1);
      ctx.beginPath();
      ctx.moveTo(-100, mt.base);
      const step = 140 * s;
      for (let x = -100; x <= w + 120; x += step) {
        const peak = mt.base - (mt.h * (0.55 + 0.45 * Math.sin((x + off) * 0.005 + m * 2.7))) * s;
        ctx.lineTo(x + step * 0.45, peak);
        ctx.lineTo(x + step, mt.base - 30 * s);
      }
      ctx.lineTo(w + 120, mt.base);
      ctx.closePath();
      const g = ctx.createLinearGradient(0, mt.base - mt.h * s, 0, mt.base);
      g.addColorStop(0, mt.c1);
      g.addColorStop(1, mt.c2);
      ctx.fillStyle = g;
      ctx.fill();
      // snow caps
      ctx.strokeStyle = mt.snow;
      ctx.lineWidth = 2 * s;
      ctx.beginPath();
      for (let x = -100; x <= w + 120; x += step) {
        const peak = mt.base - (mt.h * (0.55 + 0.45 * Math.sin((x + off) * 0.005 + m * 2.7))) * s;
        ctx.moveTo(x + step * 0.45, peak);
        ctx.lineTo(x + step * 0.32, peak + 28 * s);
        ctx.moveTo(x + step * 0.45, peak);
        ctx.lineTo(x + step * 0.58, peak + 24 * s);
      }
      ctx.stroke();
    }

    // pine forest
    const px = (x) => v.offX + x * s;
    for (let i = 0; i < 34; i++) {
      const x = px(-100 + i * 86 + Math.sin(i * 9.3) * 30);
      if (x < -80 || x > w + 80) continue;
      const ph = (90 + ((i * 37) % 110)) * s;
      const base = horizon + 20 * s;
      ctx.fillStyle = i % 3 === 0 ? '#071728' : '#0a1e32';
      ctx.beginPath();
      ctx.moveTo(x, base - ph);
      ctx.lineTo(x + 30 * s, base);
      ctx.lineTo(x - 30 * s, base);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(x, base - ph * 0.68);
      ctx.lineTo(x + 38 * s, base + 2 * s);
      ctx.lineTo(x - 38 * s, base + 2 * s);
      ctx.closePath();
      ctx.fill();
      // snow on pine
      ctx.strokeStyle = 'rgba(200, 240, 255, 0.35)';
      ctx.lineWidth = 1.5 * s;
      ctx.beginPath();
      ctx.moveTo(x - 18 * s, base - ph * 0.22);
      ctx.lineTo(x, base - ph * 0.42);
      ctx.lineTo(x + 18 * s, base - ph * 0.22);
      ctx.stroke();
    }

    // torii gate
    this.drawTorii(ctx, v, t, w * 0.28, horizon + 26 * s, 1.15 * s);
    this.drawTorii(ctx, v, t, w * 0.82, horizon + 30 * s, 0.72 * s);

    // snow floor
    const floor = ctx.createLinearGradient(0, gY - 4 * s, 0, h);
    floor.addColorStop(0, '#b9dce8');
    floor.addColorStop(0.12, '#82aec5');
    floor.addColorStop(0.4, '#314f6b');
    floor.addColorStop(1, '#091a2d');
    ctx.fillStyle = floor;
    ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);

    // snow drift edge
    ctx.beginPath();
    ctx.moveTo(0, gY + 2 * s);
    for (let x = 0; x <= w; x += 40) {
      ctx.lineTo(x, gY + 2 * s + Math.sin(x * 0.03 + t * 0.2) * 2 * s);
    }
    ctx.lineTo(w, gY + 18 * s);
    ctx.lineTo(0, gY + 18 * s);
    ctx.closePath();
    ctx.fillStyle = 'rgba(226, 248, 255, 0.78)';
    ctx.fill();

    // stone tiles
    ctx.strokeStyle = 'rgba(180, 225, 245, 0.16)';
    ctx.lineWidth = 1.2;
    const vanish = w / 2 - (v.camX - 800) * s * 0.18;
    for (let i = 0; i < 9; i++) {
      const k = i / 9;
      const y = gY + 18 * s + Math.pow(k, 1.6) * (h - gY);
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    for (let i = -8; i <= 8; i++) {
      ctx.beginPath();
      ctx.moveTo(vanish + i * 90 * s, gY + 18 * s);
      ctx.lineTo(vanish + i * 320 * s, h);
      ctx.stroke();
    }

    // ice sheen
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 4; i++) {
      const x = (0.15 + i * 0.24) * w + Math.sin(t * 0.3 + i) * 20;
      const g = ctx.createLinearGradient(x, gY, x, h);
      g.addColorStop(0, 'rgba(130, 230, 255, 0.14)');
      g.addColorStop(1, 'rgba(130, 230, 255, 0)');
      ctx.fillStyle = g;
      ctx.fillRect(x, gY, 22 * s, h - gY);
    }
    ctx.restore();
  }

  drawTorii(ctx, v, t, x, baseY, scale) {
    const c1 = '#2a0d14', c2 = '#54121c';
    ctx.save();
    ctx.translate(x, baseY);
    ctx.scale(scale, scale);
    const g = ctx.createLinearGradient(0, -260, 0, 0);
    g.addColorStop(0, c2);
    g.addColorStop(1, c1);
    // pillars
    ctx.fillStyle = g;
    ctx.fillRect(-72, -220, 16, 220);
    ctx.fillRect(56, -220, 16, 220);
    // beams
    ctx.fillRect(-96, -232, 192, 13);
    ctx.fillRect(-82, -202, 164, 10);
    ctx.fillRect(-64, -180, 128, 7);
    // roof cap
    ctx.beginPath();
    ctx.moveTo(-120, -238);
    ctx.quadraticCurveTo(-20, -258, 0, -252);
    ctx.quadraticCurveTo(20, -258, 120, -238);
    ctx.lineTo(100, -248);
    ctx.quadraticCurveTo(0, -264, -100, -248);
    ctx.closePath();
    ctx.fillStyle = '#16070c';
    ctx.fill();
    // highlight
    ctx.strokeStyle = 'rgba(255, 120, 90, 0.25)';
    ctx.lineWidth = 1.2;
    ctx.strokeRect(-72, -220, 16, 220);
    ctx.strokeRect(56, -220, 16, 220);
    // lanterns
    for (const lx of [-92, 92]) {
      const glow = 0.5 + Math.sin(t * 2.2 + lx) * 0.15;
      ctx.save();
      ctx.shadowColor = '#ffb45c';
      ctx.shadowBlur = 18;
      ctx.fillStyle = `rgba(255, 180, 92, ${glow})`;
      ctx.beginPath();
      ctx.ellipse(lx, -180, 7, 10, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  drawFoundry(ctx, t, v) {
    const { w, h } = v;
    const gY = v.groundY;
    const s = v.scale;
    const horizon = v.horizon;

    // furnace glow
    const fg = ctx.createRadialGradient(w * 0.52, horizon + 20 * s, 10, w * 0.52, horizon + 20 * s, w * 0.6);
    fg.addColorStop(0, 'rgba(255, 128, 36, 0.34)');
    fg.addColorStop(0.35, 'rgba(190, 48, 18, 0.14)');
    fg.addColorStop(1, 'rgba(40, 5, 4, 0)');
    ctx.fillStyle = fg;
    ctx.fillRect(0, 0, w, h);

    // smoke haze
    for (let i = 0; i < 4; i++) {
      const y = horizon * (0.2 + i * 0.12);
      ctx.fillStyle = `rgba(70, 26, 22, ${0.05 + i * 0.015})`;
      ctx.beginPath();
      ctx.ellipse(w * (0.18 + i * 0.2) + Math.sin(t * 0.1 + i) * 40, y, w * 0.28, 40 * s, 0, 0, TAU);
      ctx.fill();
    }

    // chimneys / towers
    const structures = [
      { x: 0.08, w: 0.11, h: 340, c: '#160709' },
      { x: 0.23, w: 0.07, h: 260, c: '#1a080a' },
      { x: 0.69, w: 0.09, h: 300, c: '#190709' },
      { x: 0.86, w: 0.13, h: 370, c: '#140507' },
    ];
    for (let i = 0; i < structures.length; i++) {
      const st = structures[i];
      const x = st.x * w - (v.camX - 800) * s * 0.08;
      const sw = st.w * w;
      const sh = st.h * s;
      const g = ctx.createLinearGradient(x, horizon - sh, x, horizon);
      g.addColorStop(0, st.c);
      g.addColorStop(1, '#0b0406');
      ctx.fillStyle = g;
      ctx.fillRect(x, horizon - sh, sw, sh + 8 * s);
      // bands
      ctx.strokeStyle = 'rgba(255, 100, 40, 0.10)';
      ctx.lineWidth = 2 * s;
      for (let k = 1; k < 6; k++) {
        ctx.beginPath();
        ctx.moveTo(x, horizon - sh + (k / 6) * sh);
        ctx.lineTo(x + sw, horizon - sh + (k / 6) * sh);
        ctx.stroke();
      }
      // top light
      ctx.save();
      ctx.shadowColor = '#ff5a1e';
      ctx.shadowBlur = 20 * s;
      ctx.fillStyle = `rgba(255, 74, 20, ${0.55 + Math.sin(t * 2 + i) * 0.2})`;
      ctx.fillRect(x + sw * 0.5 - 3 * s, horizon - sh - 4 * s, 6 * s, 6 * s);
      ctx.restore();
      // smoke from chimney
      if (i % 2 === 0) {
        for (let k = 0; k < 4; k++) {
          const age = ((t * 0.07 + k * 0.23 + i * 0.2) % 1);
          const yy = horizon - sh - 10 * s - age * 160 * s;
          const xx = x + sw * 0.5 + Math.sin(age * 4 + i) * 34 * s;
          ctx.globalAlpha = (1 - age) * 0.18;
          ctx.fillStyle = '#1a0b0b';
          ctx.beginPath();
          ctx.arc(xx, yy, (12 + age * 30) * s, 0, TAU);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
      }
    }

    // pipe network
    ctx.strokeStyle = 'rgba(60, 20, 20, 0.9)';
    ctx.lineWidth = 10 * s;
    ctx.beginPath();
    ctx.moveTo(-40, horizon - 90 * s);
    ctx.lineTo(w * 0.36, horizon - 110 * s);
    ctx.lineTo(w * 0.36, horizon - 30 * s);
    ctx.moveTo(w * 0.64, horizon - 70 * s);
    ctx.lineTo(w + 40, horizon - 120 * s);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255, 88, 30, 0.25)';
    ctx.lineWidth = 2 * s;
    ctx.beginPath();
    ctx.moveTo(-40, horizon - 95 * s);
    ctx.lineTo(w * 0.36, horizon - 115 * s);
    ctx.stroke();

    // cranes
    ctx.strokeStyle = 'rgba(40, 12, 12, 0.95)';
    ctx.lineWidth = 6 * s;
    ctx.beginPath();
    ctx.moveTo(w * 0.5, horizon);
    ctx.lineTo(w * 0.5, horizon - 220 * s);
    ctx.lineTo(w * 0.7, horizon - 160 * s);
    ctx.moveTo(w * 0.5, horizon - 220 * s);
    ctx.lineTo(w * 0.44, horizon - 190 * s);
    ctx.stroke();

    // furnace mouth
    const fx = w * 0.5;
    const fy = horizon - 30 * s;
    ctx.save();
    ctx.shadowColor = '#ff6a1e';
    ctx.shadowBlur = 40 * s;
    ctx.fillStyle = `rgba(255, 104, 24, ${0.7 + Math.sin(t * 3) * 0.1})`;
    ctx.beginPath();
    ctx.arc(fx, fy, 54 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 220, 140, 0.85)';
    ctx.beginPath();
    ctx.arc(fx, fy, 28 * s, 0, TAU);
    ctx.fill();
    ctx.restore();
    // furnace arch
    ctx.strokeStyle = '#250809';
    ctx.lineWidth = 14 * s;
    ctx.beginPath();
    ctx.arc(fx, fy, 66 * s, Math.PI, TAU);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255, 100, 30, 0.3)';
    ctx.lineWidth = 2 * s;
    ctx.beginPath();
    ctx.arc(fx, fy, 66 * s, Math.PI, TAU);
    ctx.stroke();

    // metal floor
    const floor = ctx.createLinearGradient(0, gY - 2 * s, 0, h);
    floor.addColorStop(0, '#2a1110');
    floor.addColorStop(0.15, '#180a0b');
    floor.addColorStop(0.6, '#0d0507');
    floor.addColorStop(1, '#050203');
    ctx.fillStyle = floor;
    ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);

    // hot edge
    ctx.save();
    ctx.shadowColor = '#ff6a1e';
    ctx.shadowBlur = 22 * s;
    ctx.strokeStyle = 'rgba(255, 118, 40, 0.9)';
    ctx.lineWidth = 2.5 * s;
    ctx.beginPath();
    ctx.moveTo(0, gY);
    ctx.lineTo(w, gY);
    ctx.stroke();
    ctx.restore();

    // grate lines
    ctx.strokeStyle = 'rgba(150, 60, 30, 0.15)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 11; i++) {
      const k = i / 11;
      const y = gY + Math.pow(k, 1.6) * (h - gY);
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    const vanish = w / 2 - (v.camX - 800) * s * 0.18;
    for (let i = -9; i <= 9; i++) {
      ctx.beginPath();
      ctx.moveTo(vanish + i * 90 * s, gY);
      ctx.lineTo(vanish + i * 340 * s, h);
      ctx.stroke();
    }

    // magma cracks
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 7; i++) {
      const bx = ((i * 0.17 + 0.05) * w + Math.sin(t * 0.2 + i) * 16 * s) - (v.camX - 800) * s * 0.2;
      const by = gY + (0.2 + (i % 3) * 0.22) * (h - gY);
      const len = (40 + (i % 4) * 32) * s;
      ctx.strokeStyle = `rgba(255, 86, 20, ${0.22 + (i % 3) * 0.06})`;
      ctx.lineWidth = (2 + (i % 2)) * s;
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(bx + len * 0.5, by - 4 * s);
      ctx.lineTo(bx + len, by + 3 * s);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawArenaParticles(ctx, arena, t, v) {
    const { w, h } = v;
    const gY = v.groundY;
    if (arena.key === 'neon') {
      this.drawRain(ctx, t, v);
      // floating holographic dust
      for (const d of dust) {
        const x = ((d.x + t * d.sp) % 1) * w;
        const y = gY - ((d.y * 500 + Math.sin(t * 0.6 + d.sway) * 30) * v.scale) - 60 * v.scale;
        ctx.globalAlpha = d.a;
        ctx.fillStyle = '#55e6ff';
        ctx.beginPath();
        ctx.arc(x, y, d.r * v.scale, 0, TAU);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    } else if (arena.key === 'frost') {
      this.drawSnow(ctx, t, v);
    } else {
      this.drawEmbers(ctx, t, v);
    }
  }

  drawRain(ctx, t, v) {
    const { w, h } = v;
    ctx.save();
    ctx.lineCap = 'round';
    for (const r of rain) {
      const x = ((r.x + t * 0.008) % 1) * w;
      const y = (((r.y + t * r.sp * 0.06) % 1)) * work(v, h);
      ctx.strokeStyle = `rgba(150, 220, 255, ${r.a})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - r.len * 0.15, y + r.len);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawSnow(ctx, t, v) {
    const { w, h } = v;
    for (const s of snow) {
      const x = ((s.x + Math.sin(t * 0.4 + s.sway) * 0.03 + t * 0.004) % 1) * w;
      const y = ((s.y + t * s.sp * 6) % 1) * h;
      ctx.globalAlpha = s.a;
      ctx.fillStyle = '#e9fbff';
      ctx.beginPath();
      ctx.arc(x, y, s.r * v.scale * 0.9, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  drawEmbers(ctx, t, v) {
    const { w, h } = v;
    for (const e of embers) {
      const x = ((e.x + Math.sin(t * 0.5 + e.sway) * 0.02 + t * 0.005) % 1) * w;
      const y = h - ((e.y + t * e.sp * 4) % 1) * (h - v.horizon * 0.4);
      ctx.globalAlpha = e.a * (0.6 + Math.sin(t * 3 + e.sway) * 0.4);
      ctx.fillStyle = Math.sin(e.sway) > 0 ? '#ff8a3c' : '#ffc25c';
      ctx.beginPath();
      ctx.arc(x, y, e.r * v.scale * 0.8, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  drawForeground(ctx, arena, t, v, scene) {
    const { w, h } = v;
    // bottom vignette fog
    const g = ctx.createLinearGradient(0, h * 0.72, 0, h);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(1, 'rgba(0,0,0,0.42)');
    ctx.fillStyle = g;
    ctx.fillRect(0, h * 0.72, w, h * 0.28);

    if (arena.key === 'neon') {
      // foreground rain spatter
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 12; i++) {
        const age = (t * 0.4 + i / 12) % 1;
        const x = ((i * 0.137 + 0.02) * w + Math.sin(t * 0.3 + i) * 8) % w;
        const y = v.groundY + age * (h - v.groundY) * 1.1;
        ctx.fillStyle = `rgba(90, 225, 255, ${(1 - age) * 0.14})`;
        ctx.beginPath();
        ctx.ellipse(x, y, 18 * v.scale * (0.3 + age), 2.5 * v.scale, 0, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    } else if (arena.key === 'frost') {
      // drifting foreground flakes
      for (let i = 0; i < 18; i++) {
        const x = ((i * 0.071 + t * 0.01) % 1) * w;
        const y = ((i * 0.043 + t * 0.03) % 1) * h;
        ctx.globalAlpha = 0.16;
        ctx.fillStyle = '#eaffff';
        ctx.beginPath();
        ctx.arc(x, y, (1.2 + (i % 3)) * v.scale * 1.5, 0, TAU);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    } else {
      // foreground embers / heat dust
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 14; i++) {
        const x = ((i * 0.09 + 0.02 + Math.sin(t * 0.6 + i) * 0.02) % 1) * w;
        const y = h - ((i * 0.12 + t * 0.04) % 1) * h * 0.7;
        ctx.fillStyle = `rgba(255, 122, 42, ${0.08 + (i % 3) * 0.04})`;
        ctx.beginPath();
        ctx.arc(x, y, (1.5 + (i % 4)) * v.scale, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  drawParticles(ctx, parts, t) {
    if (!parts.length) return;
    ctx.save();
    for (const p of parts) {
      const k = p.life / p.maxLife;
      if (k <= 0) continue;
      ctx.globalAlpha = clamp(k, 0, 1) * (p.alpha ?? 1);
      if (p.additive) ctx.globalCompositeOperation = 'lighter';
      else ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = p.color;
      if (p.shape === 'line') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * 0.02, p.y - p.vy * 0.02);
        ctx.stroke();
      } else if (p.shape === 'shard') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot || 0);
        ctx.beginPath();
        ctx.moveTo(0, -p.size);
        ctx.lineTo(p.size * 0.5, 0);
        ctx.lineTo(0, p.size);
        ctx.lineTo(-p.size * 0.5, 0);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (0.4 + k * 0.6), 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  drawProjectiles(ctx, projectiles, t) {
    for (const p of projectiles) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.scale(p.facing, 1);
      ctx.globalCompositeOperation = 'lighter';
      if (p.type === 'ice') {
        const r = p.radius;
        // aura
        const g = ctx.createRadialGradient(0, 0, 4, 0, 0, r * 2.6);
        g.addColorStop(0, 'rgba(255,255,255,0.95)');
        g.addColorStop(0.18, 'rgba(130,245,255,0.75)');
        g.addColorStop(0.5, 'rgba(50,180,255,0.24)');
        g.addColorStop(1, 'rgba(20,80,220,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(0, 0, r * 2.6, 0, TAU);
        ctx.fill();
        // rotating crescent blades
        for (let i = 0; i < 3; i++) {
          const rot = t * 8 + i * (TAU / 3);
          ctx.save();
          ctx.rotate(rot);
          ctx.strokeStyle = i === 0 ? 'rgba(255,255,255,0.95)' : 'rgba(120,240,255,0.8)';
          ctx.lineWidth = 4 - i * 0.8;
          ctx.beginPath();
          ctx.arc(0, 0, r * (0.85 + i * 0.14), -1.15, 1.15);
          ctx.stroke();
          ctx.restore();
        }
        // core
        ctx.fillStyle = 'rgba(255,255,255,0.95)';
        ctx.beginPath();
        ctx.ellipse(0, 0, r * 0.42, r * 0.22, 0, 0, TAU);
        ctx.fill();
        // trailing spikes
        ctx.strokeStyle = 'rgba(160, 245, 255, 0.7)';
        ctx.lineWidth = 2.4;
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * TAU;
          const len = r * (1.3 + Math.sin(t * 14 + i) * 0.2);
          ctx.beginPath();
          ctx.moveTo(Math.cos(a) * r * 0.5, Math.sin(a) * r * 0.5);
          ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
          ctx.stroke();
        }
      } else {
        const r = p.radius;
        const g = ctx.createRadialGradient(0, 0, 4, 0, 0, r * 2.8);
        g.addColorStop(0, 'rgba(255,255,240,0.95)');
        g.addColorStop(0.18, 'rgba(255,200,90,0.8)');
        g.addColorStop(0.46, 'rgba(255,80,25,0.34)');
        g.addColorStop(1, 'rgba(255,30,0,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(0, 0, r * 2.7, 0, TAU);
        ctx.fill();
        // jagged fire ring
        ctx.rotate(t * 3);
        ctx.fillStyle = 'rgba(255, 120, 30, 0.72)';
        ctx.beginPath();
        for (let i = 0; i < 12; i++) {
          const a = (i / 12) * TAU;
          const rr = i % 2 === 0 ? r * 1.12 : r * 0.7;
          ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
        }
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = 'rgba(255, 236, 170, 0.92)';
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.46, 0, TAU);
        ctx.fill();
        // flame tongues
        ctx.strokeStyle = 'rgba(255, 140, 40, 0.65)';
        ctx.lineWidth = 3;
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * TAU + t * 2;
          const len = r * (1.5 + Math.sin(t * 12 + i * 2) * 0.3);
          ctx.beginPath();
          ctx.moveTo(Math.cos(a) * r * 0.7, Math.sin(a) * r * 0.7);
          ctx.quadraticCurveTo(
            Math.cos(a + 0.3) * len, Math.sin(a + 0.3) * len,
            Math.cos(a) * len * 1.2, Math.sin(a) * len * 1.2
          );
          ctx.stroke();
        }
      }
      ctx.restore();
    }
  }

  drawEffects(ctx, effects, t) {
    for (const e of effects) {
      const k = clamp(e.life / e.maxLife, 0, 1);
      ctx.save();
      if (e.type === 'hit') {
        ctx.translate(e.x, e.y);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k;
        const size = e.size * (0.6 + (1 - k) * 0.9);
        const g = ctx.createRadialGradient(0, 0, 1, 0, 0, size * 2);
        g.addColorStop(0, '#ffffff');
        g.addColorStop(0.25, e.color || '#9ff6ff');
        g.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(0, 0, size * 2, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2.5 * k;
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * TAU + (e.seed || 0);
          const len = size * (1.4 + (i % 2) * 0.7);
          ctx.beginPath();
          ctx.moveTo(Math.cos(a) * size * 0.3, Math.sin(a) * size * 0.3);
          ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
          ctx.stroke();
        }
      } else if (e.type === 'block') {
        ctx.translate(e.x, e.y);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k * 0.9;
        ctx.strokeStyle = e.color || '#9feaff';
        ctx.lineWidth = 5 * k;
        ctx.beginPath();
        ctx.arc(0, 0, e.size * (1.2 - k * 0.5), -1.2, 1.2);
        ctx.stroke();
        ctx.lineWidth = 2 * k;
        ctx.beginPath();
        ctx.arc(0, 0, e.size * (0.8 - k * 0.3), -1.3, 1.3);
        ctx.stroke();
        for (let i = 0; i < 6; i++) {
          const a = -1.2 + (i / 5) * 2.4;
          const len = e.size * (0.5 + (1 - k) * 0.9);
          ctx.beginPath();
          ctx.moveTo(Math.cos(a) * e.size * 0.4, Math.sin(a) * e.size * 0.4);
          ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
          ctx.stroke();
        }
      } else if (e.type === 'ring') {
        ctx.translate(e.x, e.y);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k * (e.alpha || 0.7);
        ctx.strokeStyle = e.color || '#9ff6ff';
        ctx.lineWidth = (e.width || 5) * k;
        ctx.beginPath();
        ctx.ellipse(0, 0, e.size * (1.2 - k), e.size * 0.3 * (1.2 - k), 0, 0, TAU);
        ctx.stroke();
      } else if (e.type === 'slash') {
        ctx.translate(e.x, e.y);
        ctx.scale(e.facing || 1, 1);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k;
        const p = 1 - k;
        const a0 = e.angle0 ?? -1.5;
        const a1 = e.angle1 ?? 0.9;
        const r = e.size || 140;
        const grad = ctx.createLinearGradient(-r, -r, r, r);
        grad.addColorStop(0, 'rgba(255,255,255,0)');
        grad.addColorStop(0.3, e.color || '#bffaff');
        grad.addColorStop(0.7, '#ffffff');
        grad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.strokeStyle = grad;
        ctx.lineWidth = (e.width || 16) * (0.4 + k * 0.8);
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.arc(0, 0, r * (e.radius || 1) * (0.8 + p * 0.35), a0 + p * 0.5, a1 + p * 0.2);
        ctx.stroke();
        ctx.lineWidth = Math.max(1, (e.width || 16) * 0.22 * k);
        ctx.strokeStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, r * (e.radius || 1) * (0.8 + p * 0.35), a0 + p * 0.5, a1 + p * 0.2);
        ctx.stroke();
      } else if (e.type === 'shockwave') {
        ctx.translate(e.x, e.y);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k * 0.8;
        for (let i = 0; i < 3; i++) {
          ctx.strokeStyle = i === 0 ? '#ffffff' : (e.color || '#9ff6ff');
          ctx.lineWidth = (4 - i) * k;
          ctx.beginPath();
          ctx.ellipse(0, 0, (e.size || 120) * (1.1 - k) * (1 + i * 0.32), (e.size || 120) * 0.24 * (1.1 - k), 0, 0, TAU);
          ctx.stroke();
        }
      } else if (e.type === 'charge') {
        ctx.translate(e.x, e.y);
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = k * 0.85;
        const r = (e.size || 110) * (0.6 + (1 - k) * 0.7);
        ctx.strokeStyle = e.color || '#9ff6ff';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, TAU);
        ctx.stroke();
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.7, 0, TAU);
        ctx.stroke();
        for (let i = 0; i < 10; i++) {
          const a = t * 4 + (i / 10) * TAU;
          ctx.beginPath();
          ctx.moveTo(Math.cos(a) * r * 0.8, Math.sin(a) * r * 0.8);
          ctx.lineTo(Math.cos(a + 0.3) * r * 1.15, Math.sin(a + 0.3) * r * 1.15);
          ctx.stroke();
        }
      }
      ctx.restore();
    }
  }
}

function work(v, h) {
  return h;
}

// Combat engine, rounds, AI and effects
import { ATTACKS, FIGHTERS, WORLD, makeFighter } from './data.js';
import { samplePose } from './rig.js';

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const sign = (v) => (v < 0 ? -1 : 1);

const ACTIONS = ['punch', 'kick', 'special', 'jump'];
const START_ENERGY = 32;

function held(inp, action) {
  return !!(inp && inp.held && inp.held[action]);
}
function buffered(inp, action) {
  return !!(inp && inp.buffer && inp.buffer[action] > 0);
}
function consume(inp, action) {
  if (inp && inp.buffer) inp.buffer[action] = 0;
}
function overlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
function hurtbox(f) {
  const s = f.def.scale;
  const h = f.crouching ? 238 : 312;
  const w = 92 * s;
  return { x: f.x - w / 2, y: f.y - h * s, w, h: h * s };
}

class CPUControls {
  constructor() {
    this.held = { left: false, right: false, jump: false, down: false, block: false };
    this.buffer = { punch: 0, kick: 0, special: 0, jump: 0 };
  }
  update(dt) {
    for (const k of ACTIONS) if (this.buffer[k] > 0) this.buffer[k] = Math.max(0, this.buffer[k] - dt);
  }
  clearHeld() {
    for (const k of Object.keys(this.held)) this.held[k] = false;
  }
  press(action) {
    this.buffer[action] = 0.2;
    if (action === 'jump') this.held.jump = true;
  }
}

class FightAI {
  constructor(game) {
    this.game = game;
    this.input = new CPUControls();
    this.timer = 0.4;
    this.specialCooldown = 2;
    this.blockTimer = 0;
    this.reaction = 0.115;
  }

  update(dt) {
    const game = this.game;
    const inp = this.input;
    inp.update(dt);
    inp.clearHeld();
    this.specialCooldown = Math.max(0, this.specialCooldown - dt);
    if (game.phase !== 'active') {
      this.timer = Math.min(this.timer, 0.2);
      return;
    }
    const me = game.cpu;
    const opp = game.player;
    if (!me || !opp || me.state === 'ko' || opp.state === 'ko') return;

    const dist = Math.abs(opp.x - me.x);
    const toward = opp.x >= me.x ? 1 : -1;
    this.timer -= dt;
    this.blockTimer = Math.max(0, this.blockTimer - dt);

    // react to incoming projectiles
    let threat = null;
    for (const p of game.projectiles) {
      if (p.owner === me) continue;
      if (Math.abs(p.y - (me.y - 180)) < 170 && Math.abs(p.x - me.x) < 430) {
        const movingToward = Math.sign(p.vx) === Math.sign(me.x - p.x);
        if (movingToward) threat = p;
      }
    }
    if (threat && Math.random() < 0.52) {
      inp.held.block = true;
      this.blockTimer = 0.28;
      return;
    }

    // if still blocking from a decision, keep the guard up briefly
    if (this.blockTimer > 0) {
      inp.held.block = true;
      return;
    }

    if (this.timer > 0) return;
    this.timer = this.reaction + rand(0, 0.09);

    const attacking = opp.state === 'attack' && opp.attack;
    const oppThreat = attacking && opp.attack.elapsed < opp.attack.startup + opp.attack.active + 0.04;
    if (oppThreat && dist < 280 && Math.random() < 0.48) {
      inp.held.block = true;
      this.blockTimer = 0.26 + rand(0, 0.15);
      return;
    }

    if (dist > 240) {
      inp.held[toward > 0 ? 'right' : 'left'] = true;
      if (Math.random() < 0.03) inp.press('jump');
      if (me.energy >= 50 && dist > 340 && dist < 1150 && this.specialCooldown <= 0 && Math.random() < 0.32) {
        inp.press('special');
        this.specialCooldown = 2.4;
      } else if (dist < 330 && Math.random() < 0.42) {
        inp.press('kick');
      }
      return;
    }

    if (dist < 132) {
      if (Math.random() < 0.19) {
        inp.held[toward > 0 ? 'left' : 'right'] = true;
      }
      if (me.energy >= 50 && this.specialCooldown <= 0 && Math.random() < 0.16) {
        inp.press('special');
        this.specialCooldown = 2.6;
      } else if (Math.random() < 0.62) {
        inp.press(Math.random() < 0.66 ? 'punch' : 'kick');
      } else if (Math.random() < 0.17) {
        inp.held.block = true;
        this.blockTimer = 0.2;
      }
      if (Math.random() < 0.035) inp.press('jump');
      return;
    }

    // mid range: poke, step in, or defend
    if (dist > 195) inp.held[toward > 0 ? 'right' : 'left'] = true;
    else if (Math.random() < 0.22) inp.held[toward > 0 ? 'left' : 'right'] = true;
    if (me.energy >= 50 && dist > 250 && this.specialCooldown <= 0 && Math.random() < 0.19) {
      inp.press('special');
      this.specialCooldown = 3;
    } else if (Math.random() < 0.45) {
      inp.press(Math.random() < 0.5 ? 'punch' : 'kick');
    }
    if (Math.random() < 0.045) inp.press('jump');
  }
}

export class Game {
  constructor({ playerKey, cpuKey, arena, callbacks }) {
    this.callbacks = callbacks || {};
    this.arena = arena | 0;
    this.player = makeFighter(playerKey, 540, 1);
    this.cpu = makeFighter(cpuKey, 1060, -1);
    this.round = 1;
    this.phase = 'intro';
    this.phaseTime = 0;
    this.time = 0;
    this.timer = 99;
    this.hitstop = 0;
    this.shake = 0;
    this.flash = 0;
    this.particles = [];
    this.effects = [];
    this.projectiles = [];
    this.ai = new FightAI(this);
    this.playerInput = null;
    this.announcedFight = false;
    this.matchOver = false;
    this.lastRoundWinner = null;
    this.winBannerShown = false;
    this.startRound(true);
  }

  setPlayerInput(input) {
    this.playerInput = input;
  }

  sound(name, opts) {
    if (this.callbacks.sound) this.callbacks.sound(name, opts);
  }

  announce(text, sub, opts = {}) {
    if (this.callbacks.announce) this.callbacks.announce(text, sub, opts);
  }

  startRound(first = false) {
    const p = this.player;
    const c = this.cpu;
    for (const f of [p, c]) {
      f.x = f === p ? 540 : 1060;
      f.y = WORLD.ground;
      f.vx = 0;
      f.vy = 0;
      f.grounded = true;
      f.hp = f.maxHp;
      f.energy = START_ENERGY;
      f.state = 'idle';
      f.anim = 'idle';
      f.animTime = rand(0, 1.4);
      f.attack = null;
      f.hitstun = 0;
      f.blockstun = 0;
      f.blocking = false;
      f.crouching = false;
      f.combo = 0;
      f.comboTimer = 0;
      f.flash = 0;
      f.koTime = 0;
      f.hitElapsed = 0;
      f.hitDuration = 0;
      f.pose = samplePose('idle', f.animTime, f);
    }
    p.facing = 1;
    c.facing = -1;
    this.timer = 99;
    this.phase = 'intro';
    this.phaseTime = 0;
    this.hitstop = 0;
    this.shake = 0;
    this.flash = 0;
    this.projectiles.length = 0;
    this.effects.length = 0;
    this.particles.length = 0;
    this.announcedFight = false;
    this.winBannerShown = false;
    const roundName = this.round === 3 || (p.roundWins === 1 && c.roundWins === 1) ? 'FINAL ROUND' : `ROUND ${this.round}`;
    this.announce(roundName, this.round === 1 ? 'THE BLADES AWAKEN' : 'STEEL REMEMBERS', { duration: 1.5, mode: 'round' });
    this.sound('round');
    if (first) this.sound('intro');
  }

  update(dt) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 55);
    this.flash = Math.max(0, this.flash - dt * 3.8);

    if (this.phase === 'matchEnd') {
      this.updateFighterVisuals(dt);
      this.updateParticles(dt * 0.35);
      this.updateEffects(dt * 0.35);
      return;
    }
    if (this.hitstop > 0) {
      this.hitstop -= dt;
      this.updateParticles(dt * 0.18);
      this.updateEffects(dt * 0.18);
      return;
    }

    this.phaseTime += dt;
    if (this.phase === 'intro') {
      this.updateVisualOnly(dt);
      if (!this.announcedFight && this.phaseTime > 1.22) {
        this.announcedFight = true;
        this.phase = 'active';
        this.announce('FIGHT!', 'DRAW YOUR BLADE', { duration: 0.9, mode: 'fight' });
        this.sound('fight');
      }
      return;
    }

    if (this.phase === 'ko' || this.phase === 'timeup') {
      this.updateVisualOnly(dt, true);
      this.updateParticles(dt);
      this.updateEffects(dt);
      if (this.phaseTime > 2.35) this.finishRound(this.pendingWinner, this.pendingDraw);
      return;
    }

    if (this.phase === 'roundEnd') {
      this.updateVisualOnly(dt);
      this.updateParticles(dt);
      this.updateEffects(dt);
      if (this.phaseTime > 1.35) {
        if (this.matchOver) {
          this.phase = 'matchEnd';
          this.phaseTime = 0;
          if (this.callbacks.matchEnd) this.callbacks.matchEnd(this.lastRoundWinner, {
            playerWins: this.player.roundWins,
            cpuWins: this.cpu.roundWins,
          });
        } else {
          this.round += 1;
          this.startRound(false);
        }
      }
      return;
    }

    if (this.phase !== 'active') return;

    // timer
    this.timer -= dt;
    if (this.timer <= 0) {
      this.timer = 0;
      this.timeUp();
      return;
    }

    this.ai.update(dt);
    const pInput = this.playerInput || { held: {}, buffer: {} };
    this.updateFighter(this.player, this.cpu, pInput, dt);
    this.updateFighter(this.cpu, this.player, this.ai.input, dt);
    this.resolveMelee(this.player, this.cpu);
    this.resolveMelee(this.cpu, this.player);
    this.updateProjectiles(dt);
    this.separate();
    this.updateParticles(dt);
    this.updateEffects(dt);

    if (this.player.comboTimer > 0) {
      this.player.comboTimer -= dt;
      if (this.player.comboTimer <= 0) this.player.combo = 0;
    }
    if (this.cpu.comboTimer > 0) {
      this.cpu.comboTimer -= dt;
      if (this.cpu.comboTimer <= 0) this.cpu.combo = 0;
    }

    if (this.player.hp <= 0 || this.cpu.hp <= 0) return;
  }

  updateVisualOnly(dt, ko = false) {
    for (const f of [this.player, this.cpu]) {
      f.animTime += dt;
      f.flash = Math.max(0, f.flash - dt * 4);
      if (ko || f.state === 'ko') {
        f.koTime += dt;
      }
      if (f.state === 'ko') {
        f.vy += (f.grounded ? 0 : WORLD.gravity) * 0.4 * dt;
        if (!f.grounded) {
          f.y += f.vy * dt;
          if (f.y >= WORLD.ground) {
            f.y = WORLD.ground;
            f.vy = 0;
            f.grounded = true;
          }
        }
        f.x += f.vx * dt;
        f.vx *= Math.pow(0.004, dt);
        f.x = clamp(f.x, WORLD.left, WORLD.right);
        f.pose = samplePose('ko', clamp(f.koTime * 1.65, 0, 1), f);
      } else if (f.state === 'victory') {
        f.pose = samplePose('victory', f.animTime, f);
      } else if (f.state === 'hit') {
        f.hitElapsed += dt;
        if (!f.grounded) {
          f.vy += WORLD.gravity * dt;
          f.y += f.vy * dt;
          if (f.y >= WORLD.ground) { f.y = WORLD.ground; f.vy = 0; f.grounded = true; }
        }
        f.x += f.vx * dt;
        f.vx *= Math.pow(0.01, dt);
        f.pose = samplePose('hit', clamp(f.hitElapsed / Math.max(0.001, f.hitDuration), 0, 1), f);
      } else {
        f.pose = samplePose(f.anim || 'idle', f.animTime, f);
      }
      f.x = clamp(f.x, WORLD.left, WORLD.right);
    }
  }

  updateFighter(f, opp, inp, dt) {
    f.animTime += dt;
    f.flash = Math.max(0, f.flash - dt * 4.2);
    if (f.state === 'ko') {
      f.koTime += dt;
      f.pose = samplePose('ko', clamp(f.koTime * 1.65, 0, 1), f);
      return;
    }

    const canFace = f.state !== 'attack' && f.state !== 'hit' && f.blockstun <= 0;
    if (canFace) f.facing = opp.x >= f.x ? 1 : -1;

    if (f.hitstun > 0) {
      f.hitstun -= dt;
      f.hitElapsed += dt;
      f.blocking = false;
      f.attack = null;
      this.applyPhysics(f, dt);
      f.pose = samplePose('hit', clamp(f.hitElapsed / Math.max(0.001, f.hitDuration), 0, 1), f);
      if (f.hitstun <= 0) {
        f.state = f.grounded ? 'idle' : 'jump';
        f.anim = f.grounded ? 'idle' : 'jumpDown';
        f.animTime = 0;
      }
      return;
    }

    if (f.blockstun > 0) {
      f.blockstun -= dt;
      f.state = 'block';
      f.blocking = true;
      f.vx *= Math.pow(0.002, dt);
      this.applyPhysics(f, dt);
      f.pose = samplePose('block', 1, f);
      return;
    }

    if (f.state === 'attack' && f.attack) {
      const a = f.attack;
      a.elapsed += dt;
      if (!a.slashSpawned && a.elapsed >= a.startup) {
        a.slashSpawned = true;
        this.spawnSlash(f, a);
      }
      if (!a.spawned && a.base.spawnProjectile !== undefined && a.elapsed >= a.base.spawnProjectile) {
        a.spawned = true;
        this.spawnProjectile(f, a);
      }
      // special cancel window
      if (a.contact && a.elapsed >= a.startup * 0.72) {
        for (const action of ['special', 'kick', 'punch']) {
          if (!a.base.chain.includes(action)) continue;
          if (!buffered(inp, action)) continue;
          if (this.startAttack(f, action)) {
            consume(inp, action);
            return;
          }
        }
      }
      this.applyPhysics(f, dt);
      if (a.elapsed >= a.total) {
        f.attack = null;
        if (f.grounded) {
          f.state = 'idle';
          f.anim = 'idle';
          f.animTime = 0;
        } else {
          f.state = 'jump';
          f.anim = 'jumpDown';
        }
      } else {
        f.pose = samplePose(a.key, clamp(a.elapsed / a.total, 0, 1), f);
      }
      return;
    }

    // actions that can start from the ground
    if (f.grounded) {
      f.crouching = false;
      const blocking = held(inp, 'block');
      f.blocking = blocking;
      if (blocking) {
        f.state = 'block';
        f.vx *= Math.pow(0.001, dt);
        f.energy = Math.min(f.maxEnergy, f.energy + dt * 1.8);
        f.pose = samplePose('block', 1, f);
        return;
      }
      if (buffered(inp, 'punch') && this.startAttack(f, 'punch')) { consume(inp, 'punch'); return; }
      if (buffered(inp, 'kick') && this.startAttack(f, 'kick')) { consume(inp, 'kick'); return; }
      if (buffered(inp, 'special') && this.startAttack(f, 'special')) { consume(inp, 'special'); return; }
      if (buffered(inp, 'jump')) {
        consume(inp, 'jump');
        f.vy = -f.def.jump;
        f.grounded = false;
        f.state = 'jump';
        f.anim = 'jumpUp';
        f.animTime = 0;
        f.vx = (held(inp, 'left') ? -1 : held(inp, 'right') ? 1 : 0) * f.def.speed * 0.78;
        this.spawnDust(f.x, WORLD.ground, 6, f.def.colors.accent);
        this.sound('jump');
      }
      if (held(inp, 'down') && f.grounded) {
        f.crouching = true;
        f.state = 'crouch';
        f.vx *= Math.pow(0.0001, dt);
        f.pose = samplePose('crouch', clamp((f.animTime = Math.min(f.animTime + dt, 0.16)) / 0.16, 0, 1), f);
        return;
      }
      // walking
      let move = 0;
      if (held(inp, 'left')) move -= 1;
      if (held(inp, 'right')) move += 1;
      if (move !== 0) {
        const forward = move === f.facing;
        f.vx = move * (forward ? f.def.speed : f.def.backSpeed);
        f.state = forward ? 'walk' : 'back';
        f.anim = forward ? 'walk' : 'backwalk';
        f.walkDust += dt;
        if (f.walkDust > 0.16 && f.grounded) {
          f.walkDust = 0;
          this.spawnDust(f.x - f.facing * 24, WORLD.ground, 1, f.def.colors.accent, 0.42);
        }
      } else {
        f.vx *= Math.pow(0.0001, dt);
        f.state = f.state === 'crouch' ? 'crouch' : 'idle';
        if (f.state === 'idle') f.anim = 'idle';
      }
      this.applyPhysics(f, dt);
      if (f.state === 'idle' || f.state === 'walk' || f.state === 'back') {
        f.pose = samplePose(f.anim, f.animTime, f);
      } else if (f.state === 'crouch') {
        f.pose = samplePose('crouch', 1, f);
      }
      return;
    }

    // airborne
    f.state = 'jump';
    f.crouching = false;
    f.blocking = false;
    if (held(inp, 'left')) f.vx = Math.max(-f.def.speed * 0.6, f.vx - f.def.speed * 1.5 * dt);
    else if (held(inp, 'right')) f.vx = Math.min(f.def.speed * 0.6, f.vx + f.def.speed * 1.5 * dt);
    if (buffered(inp, 'punch') && this.startAttack(f, 'punch')) { consume(inp, 'punch'); this.applyPhysics(f, dt); return; }
    if (buffered(inp, 'kick') && this.startAttack(f, 'kick')) { consume(inp, 'kick'); this.applyPhysics(f, dt); return; }
    this.applyPhysics(f, dt);
    f.pose = samplePose(f.vy < 40 ? 'jumpUp' : 'jumpDown', clamp(0.3 + Math.abs(f.vy) / 1200, 0, 1), f);
  }

  applyPhysics(f, dt) {
    f.x += f.vx * dt;
    f.x = clamp(f.x, WORLD.left, WORLD.right);
    if (!f.grounded) {
      f.vy += WORLD.gravity * dt;
      f.y += f.vy * dt;
      if (f.y >= WORLD.ground) {
        f.y = WORLD.ground;
        f.vy = 0;
        f.grounded = true;
        this.spawnDust(f.x, WORLD.ground, 5, f.def.colors.accent, 0.8);
        if (f.state === 'jump' || f.state === 'attack') {
          f.attack = null;
          f.state = 'idle';
          f.anim = 'idle';
          f.animTime = 0;
        }
      }
    } else {
      f.y = WORLD.ground;
    }
    if (f.state !== 'walk' && f.state !== 'back') f.vx *= Math.pow(0.02, dt);
  }

  startAttack(f, key) {
    const base = ATTACKS[key];
    if (!base) return false;
    if (f.state === 'attack' && f.attack) {
      const old = f.attack;
      if (!old.contact || old.elapsed < old.startup * 0.7) return false;
      if (!old.base.chain.includes(key)) return false;
    } else if (f.state === 'hit' || f.state === 'ko' || f.blockstun > 0 || f.state === 'victory') {
      return false;
    }
    if (base.cost && f.energy < base.cost) {
      this.sound('deny');
      return false;
    }
    if (base.cost) f.energy -= base.cost;

    const speedMod = f.def.speedMod;
    const startup = base.startup * speedMod;
    const active = base.active;
    const recovery = base.recovery * speedMod;
    const total = startup + active + recovery;
    const scale = f.def.range;
    f.attack = {
      key,
      base,
      elapsed: 0,
      startup,
      active,
      recovery,
      total,
      damage: base.damage * f.def.power,
      hitstun: base.hitstun,
      blockstun: base.blockstun,
      knockback: base.knockback,
      hitbox: {
        x: base.hitbox.x * scale,
        y: base.hitbox.y,
        w: base.hitbox.w * scale,
        h: base.hitbox.h,
      },
      hitDone: false,
      contact: false,
      slashSpawned: false,
      spawned: false,
      facing: f.facing,
    };
    f.state = 'attack';
    f.anim = key;
    f.animTime = 0;
    f.vx *= 0.2;
    f.crouching = false;
    f.pose = samplePose(key, 0, f);
    this.sound('whoosh', { heavy: key === 'kick', special: key === 'special' });
    if (key === 'special') {
      this.flash = Math.max(this.flash, 0.09);
      this.shake = Math.max(this.shake, 4);
      this.sound('charge');
      this.addEffect({
        type: 'charge', x: f.x, y: f.y - 175, size: 120, life: 0.45, maxLife: 0.45, color: f.def.colors.glow,
      });
      for (let i = 0; i < 18; i++) {
        const a = rand(0, TAU);
        this.addParticle({
          x: f.x + Math.cos(a) * 55, y: f.y - 170 + Math.sin(a) * 70,
          vx: -Math.cos(a) * rand(30, 130), vy: -Math.sin(a) * rand(30, 130),
          life: rand(0.3, 0.7), maxLife: 0.7, size: rand(1.5, 4),
          color: f.def.colors.accent, additive: true, alpha: 0.9,
        });
      }
    }
    return true;
  }

  spawnSlash(f, a) {
    const heavy = a.key === 'kick';
    const special = a.key === 'special';
    const y = f.y - (special ? 230 : heavy ? 175 : 225);
    this.addEffect({
      type: 'slash',
      x: f.x + f.facing * 30,
      y,
      facing: f.facing,
      size: special ? 235 : heavy ? 160 : 112,
      width: special ? 26 : heavy ? 18 : 11,
      color: f.def.colors.accent,
      life: special ? 0.38 : 0.2,
      maxLife: special ? 0.38 : 0.2,
      angle0: special ? -1.85 : heavy ? -1.5 : -1.15,
      angle1: special ? 0.75 : heavy ? 0.7 : 0.55,
      radius: special ? 1.05 : 0.9,
    });
    if (special) {
      this.shake = Math.max(this.shake, 7);
      for (let i = 0; i < 24; i++) {
        this.addParticle({
          x: f.x + f.facing * rand(10, 160), y: y + rand(-120, 120),
          vx: f.facing * rand(50, 340), vy: rand(-180, 80),
          life: rand(0.25, 0.6), maxLife: 0.6, size: rand(1.4, 4.2),
          color: f.def.colors.accent, additive: true, alpha: 0.9, shape: 'shard', rot: rand(0, TAU),
        });
      }
    }
  }

  spawnProjectile(f, a) {
    const sp = f.def.special;
    const direction = f.facing;
    this.projectiles.push({
      x: f.x + direction * 96,
      y: f.y - 212,
      vx: direction * sp.speed,
      facing: direction,
      owner: f,
      ownerKey: f.key,
      type: sp.type,
      radius: sp.radius,
      damage: sp.damage * f.def.power,
      hitstun: 0.43,
      blockstun: 0.24,
      knockback: 225,
      life: 2.2,
      hit: false,
      trailTime: 0,
      color: f.def.colors.accent,
    });
    this.addEffect({
      type: 'ring', x: f.x + direction * 80, y: f.y - 212, size: 80, width: 5,
      life: 0.4, maxLife: 0.4, color: f.def.colors.accent, alpha: 0.8,
    });
    this.flash = Math.max(this.flash, 0.18);
    this.shake = Math.max(this.shake, 8);
    this.sound('special');
  }

  resolveMelee(attacker, defender) {
    const a = attacker.attack;
    if (!a || a.hitDone) return;
    if (a.elapsed < a.startup || a.elapsed > a.startup + a.active) return;
    const box = {
      x: a.facing > 0 ? attacker.x + a.hitbox.x : attacker.x - a.hitbox.x - a.hitbox.w,
      y: attacker.y + a.hitbox.y,
      w: a.hitbox.w,
      h: a.hitbox.h,
    };
    const hurt = hurtbox(defender);
    if (!overlap(box, hurt)) return;
    a.hitDone = true;
    a.contact = true;
    const contact = {
      x: defender.x - a.facing * 22,
      y: clamp(box.y + box.h * 0.45, hurt.y, hurt.y + hurt.h),
    };
    this.applyHit(attacker, defender, a, contact, false);
  }

  applyHit(attacker, defender, data, contact, isProjectile) {
    if (defender.state === 'ko' || this.phase !== 'active') return;
    const baseDamage = data.damage || 40;
    const chip = data.base ? data.base.chip : 0.15;

    // blocking check
    if (defender.blocking && defender.blockstun <= 0 && defender.grounded && defender.state !== 'hit') {
      const facingAttacker = (attacker.x > defender.x && defender.facing > 0) || (attacker.x < defender.x && defender.facing < 0);
      if (facingAttacker || isProjectile) {
        const chipDamage = Math.max(1, baseDamage * chip);
        defender.hp = Math.max(0, defender.hp - chipDamage);
        defender.energy = Math.min(defender.maxEnergy, defender.energy + baseDamage * 0.2);
        defender.blockstun = data.blockstun + 0.03;
        defender.state = 'block';
        defender.vx = sign(attacker.x - defender.x) * (data.knockback || 80) * 0.32;
        attacker.combo = 0;
        attacker.comboTimer = 0;
        this.hitstop = Math.max(this.hitstop, 0.028);
        this.shake = Math.max(this.shake, 2.6);
        this.spawnBlockSpark(contact, defender.def.colors.accent);
        this.sound('block');
        if (defender.hp <= 0) this.beginKO(attacker, defender);
        return;
      }
    }

    const counter = defender.state === 'attack' && defender.attack && defender.attack.elapsed < defender.attack.startup;
    const continuing = defender.hitstun > 0;
    attacker.combo = continuing ? attacker.combo + 1 : 1;
    attacker.comboTimer = 0.9 + (data.hitstun || 0.2);
    attacker.hitCount += 1;
    const scaling = Math.max(0.42, 1 - (attacker.combo - 1) * 0.078);
    const damage = Math.round(baseDamage * scaling * (counter ? 1.18 : 1));
    defender.hp = Math.max(0, defender.hp - damage);
    defender.hitstun = (data.hitstun || 0.2) + (counter ? 0.08 : 0) + (isProjectile ? 0.05 : 0);
    defender.hitDuration = defender.hitstun;
    defender.hitElapsed = 0;
    defender.state = 'hit';
    defender.blocking = false;
    defender.blockstun = 0;
    defender.attack = null;
    defender.flash = 0.7;
    defender.vx = data.facing ? data.facing * (data.knockback || 80) : sign(defender.x - attacker.x) * (data.knockback || 80);
    if (isProjectile) {
      defender.vy = -210;
      defender.grounded = false;
    }
    defender.energy = Math.min(defender.maxEnergy, defender.energy + damage * 0.13);
    attacker.energy = Math.min(attacker.maxEnergy, attacker.energy + damage * 0.17);
    this.hitstop = Math.max(this.hitstop, (data.base ? data.base.hitstop : 0.04) * (counter ? 1.35 : 1));
    this.shake = Math.max(this.shake, (data.base ? data.base.shake : 5) * (counter ? 1.3 : 1));
    this.flash = Math.max(this.flash, isProjectile ? 0.22 : 0.12);

    const size = isProjectile ? 46 : data.key === 'kick' ? 34 : data.key === 'special' ? 52 : 24;
    this.spawnHitSpark(contact, attacker.def.colors.accent, size);
    this.addEffect({
      type: 'ring', x: contact.x, y: contact.y, size: size * 1.1, width: 4,
      life: 0.32, maxLife: 0.32, color: attacker.def.colors.accent, alpha: 0.7,
    });
    for (let i = 0; i < (isProjectile ? 18 : counter ? 14 : 9); i++) {
      const a = rand(0, TAU);
      const sp = rand(80, isProjectile ? 520 : 360);
      this.addParticle({
        x: contact.x, y: contact.y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 40,
        life: rand(0.2, 0.55), maxLife: 0.55, size: rand(1.2, 3.4),
        color: i % 3 === 0 ? '#ffffff' : attacker.def.colors.accent,
        additive: true, alpha: 0.95, shape: i % 4 === 0 ? 'line' : 'circle',
        shape2: 'line',
      });
    }
    this.sound(counter ? 'counter' : 'hit', { heavy: isProjectile || data.key === 'kick' });
    if (attacker.combo >= 2) this.sound('combo', { count: attacker.combo });
    if (defender.hp <= 0) this.beginKO(attacker, defender);
  }

  beginKO(winner, loser) {
    if (this.phase !== 'active') return;
    loser.hp = 0;
    loser.state = 'ko';
    loser.koTime = 0;
    loser.hitstun = 0;
    loser.blockstun = 0;
    loser.attack = null;
    loser.vy = -320;
    loser.grounded = false;
    loser.vx = sign(loser.x - winner.x) * 240;
    winner.state = 'victory';
    winner.anim = 'victory';
    winner.animTime = 0;
    winner.attack = null;
    winner.blocking = false;
    winner.crouching = false;
    winner.vx = 0;
    this.phase = 'ko';
    this.phaseTime = 0;
    this.pendingWinner = winner;
    this.pendingDraw = false;
    this.matchOver = winner.roundWins + 1 >= 2;
    this.winBannerShown = false;
    this.hitstop = 0.09;
    this.shake = 18;
    this.flash = 0.5;
    this.sound('ko');
    this.announce('K.O.', 'FINISH', { duration: 1.6, mode: 'ko' });
    this.addEffect({ type: 'shockwave', x: loser.x, y: loser.y - 6, size: 150, life: 0.6, maxLife: 0.6, color: winner.def.colors.accent });
    for (let i = 0; i < 36; i++) {
      const a = rand(0, TAU);
      this.addParticle({
        x: loser.x + rand(-30, 30), y: loser.y - rand(40, 260),
        vx: Math.cos(a) * rand(80, 440), vy: Math.sin(a) * rand(80, 440) - 100,
        life: rand(0.5, 1.3), maxLife: 1.3, size: rand(1.5, 4.5),
        color: i % 3 === 0 ? '#ffffff' : winner.def.colors.accent,
        additive: true, alpha: 0.9, shape: 'line',
      });
    }
  }

  timeUp() {
    if (this.phase !== 'active') return;
    this.phase = 'timeup';
    this.phaseTime = 0;
    const p = this.player, c = this.cpu;
    if (Math.abs(p.hp - c.hp) < 1) {
      this.pendingDraw = true;
      this.pendingWinner = null;
      this.matchOver = false;
      this.sound('timeup');
      this.announce('TIME UP', 'DRAW', { duration: 1.7, mode: 'ko' });
      return;
    }
    const winner = p.hp > c.hp ? p : c;
    const loser = winner === p ? c : p;
    this.pendingDraw = false;
    this.pendingWinner = winner;
    this.matchOver = winner.roundWins + 1 >= 2;
    winner.state = 'victory';
    winner.anim = 'victory';
    winner.animTime = 0;
    loser.state = 'idle';
    this.sound('timeup');
    this.announce('TIME UP', `${winner.def.name} LEADS`, { duration: 1.7, mode: 'ko' });
  }

  finishRound(winner, draw) {
    if (draw || !winner) {
      this.announce('DRAW', 'ROUND REPLAYED', { duration: 1.3, mode: 'round' });
      this.phase = 'roundEnd';
      this.phaseTime = 0;
      this.matchOver = false;
      return;
    }
    if (this.phase !== 'roundEnd') {
      winner.roundWins += 1;
      this.lastRoundWinner = winner;
      this.phase = 'roundEnd';
      this.phaseTime = 0;
      this.matchOver = winner.roundWins >= 2;
      this.announce(`${winner.def.name} WINS`, `ROUND ${this.round}`, {
        duration: 1.25, mode: 'win', color: winner.def.accent,
      });
      this.sound('win');
      if (this.callbacks.roundEnd) {
        this.callbacks.roundEnd({
          winner: winner.key,
          playerWins: this.player.roundWins,
          cpuWins: this.cpu.roundWins,
          matchOver: this.matchOver,
          round: this.round,
        });
      }
    }
  }

  updateProjectiles(dt) {
    const list = this.projectiles;
    for (let i = list.length - 1; i >= 0; i--) {
      const p = list[i];
      p.x += p.vx * dt;
      p.life -= dt;
      p.trailTime += dt;
      if (p.trailTime > 0.028) {
        p.trailTime = 0;
        const back = p.facing > 0 ? -1 : 1;
        for (let k = 0; k < 2; k++) {
          this.addParticle({
            x: p.x + back * rand(10, p.radius * 1.4), y: p.y + rand(-p.radius, p.radius),
            vx: p.vx * 0.1 + rand(-40, 40), vy: rand(-70, 70),
            life: rand(0.15, 0.38), maxLife: 0.38, size: rand(1.2, 3.1),
            color: p.type === 'ice' ? '#9ff7ff' : '#ffb347', additive: true, alpha: 0.8,
            shape: p.type === 'ice' ? 'shard' : 'circle', rot: rand(0, TAU),
          });
        }
      }
      const target = p.owner === this.player ? this.cpu : this.player;
      if (!p.hit && target && target.state !== 'ko') {
        const hb = hurtbox(target);
        const closestX = clamp(p.x, hb.x, hb.x + hb.w);
        const closestY = clamp(p.y, hb.y, hb.y + hb.h);
        const dx = p.x - closestX;
        const dy = p.y - closestY;
        if (dx * dx + dy * dy < p.radius * p.radius) {
          p.hit = true;
          this.applyHit(p.owner, target, {
            damage: p.damage,
            hitstun: p.hitstun,
            blockstun: p.blockstun,
            knockback: p.knockback,
            facing: p.facing,
            base: { chip: 0.22, hitstop: 0.07, shake: 12 },
            key: 'special',
          }, { x: p.x, y: p.y }, true);
          this.addEffect({
            type: 'shockwave', x: p.x, y: p.y, size: p.radius * 2.2, life: 0.45, maxLife: 0.45,
            color: p.type === 'ice' ? '#bffaff' : '#ffb347',
          });
          p.life = 0;
        }
      }
      if (p.x < -100 || p.x > WORLD.w + 100) p.life = 0;
    }
    // projectile clash
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        const a = list[i], b = list[j];
        if (!a || !b || a.owner === b.owner) continue;
        if (Math.abs(a.x - b.x) < a.radius + b.radius && Math.abs(a.y - b.y) < a.radius + b.radius) {
          a.life = 0; b.life = 0;
          const x = (a.x + b.x) / 2, y = (a.y + b.y) / 2;
          this.addEffect({ type: 'shockwave', x, y, size: 170, life: 0.55, maxLife: 0.55, color: '#ffffff' });
          this.spawnHitSpark({ x, y }, '#ffe6a8', 50);
          this.shake = Math.max(this.shake, 10);
          this.flash = Math.max(this.flash, 0.24);
          this.sound('clash');
          for (let k = 0; k < 24; k++) {
            const ang = rand(0, TAU);
            this.addParticle({
              x, y, vx: Math.cos(ang) * rand(80, 520), vy: Math.sin(ang) * rand(80, 520),
              life: rand(0.3, 0.8), maxLife: 0.8, size: rand(1.5, 4),
              color: k % 2 ? '#9ff7ff' : '#ffb347', additive: true, alpha: 0.9, shape: 'line',
            });
          }
        }
      }
    }
    for (let i = list.length - 1; i >= 0; i--) if (list[i].life <= 0) list.splice(i, 1);
  }

  separate() {
    const p = this.player, c = this.cpu;
    if (!p || !c || p.state === 'ko' || c.state === 'ko') return;
    const min = 82;
    const dx = c.x - p.x;
    if (Math.abs(dx) < min) {
      const push = (min - Math.abs(dx)) / 2;
      const dir = dx >= 0 ? 1 : -1;
      p.x = clamp(p.x - dir * push, WORLD.left, WORLD.right);
      c.x = clamp(c.x + dir * push, WORLD.left, WORLD.right);
    }
  }

  spawnDust(x, y, count, color, scale = 1) {
    for (let i = 0; i < count; i++) {
      this.addParticle({
        x: x + rand(-18, 18), y: y - rand(0, 8),
        vx: rand(-80, 80) * scale, vy: rand(-95, -20) * scale,
        life: rand(0.25, 0.6), maxLife: 0.6, size: rand(2, 5) * scale,
        color: i % 2 ? color : '#cfd8e8', additive: false, alpha: 0.28, layer: 'back',
      });
    }
  }

  spawnHitSpark(contact, color, size) {
    this.addEffect({
      type: 'hit', x: contact.x, y: contact.y, size, color, life: 0.3, maxLife: 0.3, seed: rand(0, TAU),
    });
  }

  spawnBlockSpark(contact, color) {
    this.addEffect({
      type: 'block', x: contact.x, y: contact.y, size: 46, color: color || '#9ff6ff', life: 0.3, maxLife: 0.3,
    });
    for (let i = 0; i < 8; i++) {
      this.addParticle({
        x: contact.x, y: contact.y, vx: rand(-180, 180), vy: rand(-180, 120),
        life: rand(0.15, 0.35), maxLife: 0.35, size: rand(1, 2.6),
        color: i % 2 ? '#ffffff' : (color || '#9ff6ff'), additive: true, alpha: 0.9, shape: 'line',
      });
    }
  }

  addParticle(p) {
    if (this.particles.length > 520) this.particles.shift();
    this.particles.push(p);
  }

  addEffect(e) {
    if (this.effects.length > 90) this.effects.shift();
    this.effects.push(e);
  }

  updateParticles(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) { this.particles.splice(i, 1); continue; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += (p.gravity ?? 520) * dt;
      p.vx *= Math.pow(0.2, dt);
      if (p.rot !== undefined) p.rot += dt * 6;
    }
  }

  updateEffects(dt) {
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      if (e.life <= 0) this.effects.splice(i, 1);
    }
  }

  getHud() {
    const p = this.player, c = this.cpu;
    return {
      player: {
        hp: p.hp, maxHp: p.maxHp, energy: p.energy, wins: p.roundWins, combo: p.combo,
        comboTimer: p.comboTimer, key: p.key,
      },
      cpu: {
        hp: c.hp, maxHp: c.maxHp, energy: c.energy, wins: c.roundWins, combo: c.combo,
        comboTimer: c.comboTimer, key: c.key,
      },
      timer: Math.ceil(this.timer),
      round: this.round,
      phase: this.phase,
    };
  }
}

