import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.screenshot({ path: join(out, 'title.png') });
await page.click('#btn-start');
await page.waitForTimeout(900);
await page.screenshot({ path: join(out, 'select.png') });
await page.click('[data-fighter="raze"]');
await page.waitForTimeout(500);
await page.screenshot({ path: join(out, 'select-raze.png') });
await page.click('#btn-fight');
await page.waitForTimeout(1800);
await page.screenshot({ path: join(out, 'fight-intro.png') });
// move and attack
await page.keyboard.down('KeyD');
await page.waitForTimeout(500);
await page.keyboard.up('KeyD');
await page.waitForTimeout(150);
await page.keyboard.press('KeyJ');
await page.waitForTimeout(120);
await page.screenshot({ path: join(out, 'fight-punch.png') });
await page.waitForTimeout(700);
await page.keyboard.press('KeyK');
await page.waitForTimeout(160);
await page.screenshot({ path: join(out, 'fight-kick.png') });
await page.waitForTimeout(500);
// spam special after energy maybe
await page.keyboard.press('Space');
await page.waitForTimeout(280);
await page.screenshot({ path: join(out, 'fight-special.png') });
await page.waitForTimeout(2200);
await page.screenshot({ path: join(out, 'fight-later.png') });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

