396: function handleMenuKey(e) {
397:   if ($('screen-help').classList.contains('is-active')) {
398:     if (e.code === 'Escape' || e.code === 'Enter') closeHelp();
399:     return true;
400:   }
401:   if ($('screen-pause').classList.contains('is-active')) {
402:     if (e.code === 'Escape') togglePause();
403:     return true;
404:   }
405:   if ($('screen-match').classList.contains('is-active')) {
406:     if (e.code === 'Enter') {
407:       $('screen-match').classList.remove('is-active');
408:       startFight();
409:     }
410:     return true;
411:   }
412:   if (app.scene === 'title') {
413:     if (e.code === 'Enter' || e.code === 'NumpadEnter') {
414:       showSelect();
415:       audio.play('confirm');
416:       return true;
417:     }
418:     return false;
419:   }
420:   if (app.scene === 'select') {
421:     if (e.code === 'Escape') {
422:       showTitle();
423:       audio.play('select');
424:       return true;
425:     }
426:     if (e.code === 'Enter' || e.code === 'NumpadEnter') {
427:       startFight();
428:       return true;
429:     }
430:     if (e.code === 'ArrowLeft' || e.code === 'KeyA') {
431:       if (app.selectedFighter !== 'akira') selectFighter('akira');
432:       return true;
433:     }
434:     if (e.code === 'ArrowRight' || e.code === 'KeyD') {
435:       if (app.selectedFighter !== 'raze') selectFighter('raze');
436:       return true;
437:     }
438:     if (e.code === 'ArrowUp' || e.code === 'KeyW') {
439:       selectArena((app.selectedArena + ARENAS.length - 1) % ARENAS.length);
440:       return true;
441:     }
442:     if (e.code === 'ArrowDown' || e.code === 'KeyS') {
443:       selectArena((app.selectedArena + 1) % ARENAS.length);
444:       return true;
445:     }
446:     if (e.code === 'Digit1' || e.code === 'Numpad1') { selectArena(0); return true; }
447:     if (e.code === 'Digit2' || e.code === 'Numpad2') { selectArena(1); return true; }
448:     if (e.code === 'Digit3' || e.code === 'Numpad3') { selectArena(2); return true; }
449:     return false;
450:   }
451:   return false;
452: }
