605: function fitCanvas(canvas) {
606:   const dpr = Math.min(2, window.devicePixelRatio || 1);
607:   const w = Math.max(1, Math.round(canvas.clientWidth));
608:   const h = Math.max(1, Math.round(canvas.clientHeight));
