215:     moonG.addColorStop(0.55, '#b8d9ea');
216:     moonG.addColorStop(1, '#7c9fbf');
217:     ctx.fillStyle = moonG;
218:     ctx.beginPath();
219:     ctx.arc(mx, my, mr, 0, TAU);
220:     ctx.fill();
221:     ctx.fillStyle = 'rgba(50, 80, 120, 0.18)';
222:     ctx.beginPath();
223:     ctx.arc(mx - mr * 0.3, my - mr * 0.15, mr * 0.25, 0, TAU);
224:     ctx.arc(mx + mr * 0.35, my + mr * 0.2, mr * 0.16, 0, TAU);
225:     ctx.fill();
226: 
227:     // glow behind skyline
228:     const bg = ctx.createRadialGradient(w * 0.64, horizon, 10, w * 0.64, horizon, w * 0.7);
229:     bg.addColorStop(0, 'rgba(255, 38, 130, 0.20)');
230:     bg.addColorStop(0.35, 'rgba(93, 45, 180, 0.14)');
231:     bg.addColorStop(1, 'rgba(0,0,0,0)');
232:     ctx.fillStyle = bg;
233:     ctx.fillRect(0, 0, w, h);
234: 
235:     const bx = (x) => v.offX + x * s;
236: 
237:     // far skyline
238:     for (const b of buildingsFar) {
239:       const x = bx(b.x);
240:       const bw = b.w * s;
241:       const bh = b.h * s;
242:       if (x + bw < -20 || x > w + 20) continue;
243:       ctx.fillStyle = b.s > 0.55 ? '#0a1129' : '#0c1430';
244:       ctx.fillRect(x, horizon - bh, bw, bh + 4 * s);
245:       ctx.fillStyle = 'rgba(96, 165, 230, 0.20)';
246:       for (let wy = horizon - bh + 10 * s; wy < horizon - 8 * s; wy += 13 * s) {
247:         for (let wx = x + 5 * s; wx < x + bw - 5 * s; wx += 11 * s) {
248:           if (((wx + wy) | 0) % 29 < 16) ctx.fillRect(wx, wy, 3 * s, 4 * s);
249:         }
250:       }
251:     }
252: 
253:     // mid skyline
254:     for (let i = 0; i < buildingsMid.length; i++) {
255:       const b = buildingsMid[i];
256:       const x = bx(b.x);
257:       const bw = b.w * s;
258:       const bh = b.h * s;
259:       if (x + bw < -40 || x > w + 40) continue;
260:       const grad = ctx.createLinearGradient(x, horizon - bh, x, horizon);
261:       grad.addColorStop(0, '#111b3f');
262:       grad.addColorStop(1, '#080d20');
263:       ctx.fillStyle = grad;
264:       ctx.fillRect(x, horizon - bh, bw, bh + 3 * s);
265: 
266:       // roof antenna
267:       if (b.s > 0.66) {
268:         ctx.strokeStyle = 'rgba(100, 180, 240, 0.3)';
269:         ctx.lineWidth = 1.5 * s;
270:         ctx.beginPath();
271:         ctx.moveTo(x + bw * 0.5, horizon - bh);
272:         ctx.lineTo(x + bw * 0.5, horizon - bh - 28 * s);
273:         ctx.stroke();
274:         ctx.fillStyle = 'rgba(255, 50, 120, 0.9)';
275:         ctx.beginPath();
276:         ctx.arc(x + bw * 0.5, horizon - bh - 29 * s, 2.2 * s, 0, TAU);
277:         ctx.fill();
278:       }
279: 
280:       // windows
281:       ctx.fillStyle = 'rgba(255, 186, 92, 0.38)';
282:       for (let wy = horizon - bh + 16 * s; wy < horizon - 12 * s; wy += 17 * s) {
283:         for (let wx = x + 7 * s; wx < x + bw - 8 * s; wx += 14 * s) {
284:           const n = Math.sin(wx * 12.3 + wy * 2.1 + i) * 1000;
285:           if (n - Math.floor(n) > 0.54) ctx.fillRect(wx, wy, 4.5 * s, 6 * s);
286:         }
287:       }
288:       // neon building edge
289:       if (i % 3 === 0) {
290:         ctx.strokeStyle = i % 6 === 0 ? 'rgba(80, 230, 255, 0.5)' : 'rgba(255, 61, 158, 0.45)';
291:         ctx.lineWidth = 2 * s;
292:         ctx.beginPath();
293:         ctx.moveTo(x + bw, horizon - bh + 10 * s);
294:         ctx.lineTo(x + bw, horizon);
295:         ctx.stroke();
296:       }
297:     }
298: 
299:     // hanging neon signs / billboards
300:     const signGlow = 0.7 + Math.sin(t * 6.5) * 0.08;
301:     ctx.save();
302:     ctx.shadowColor = '#54e6ff';
303:     ctx.shadowBlur = 24 * s;
304:     ctx.fillStyle = `rgba(54, 230, 255, ${0.22 * signGlow})`;
305:     const signX = w * 0.13 - (v.camX - 800) * s * 0.1;
306:     const signY = horizon * 0.55;
307:     ctx.fillRect(signX, signY, 38 * s, 120 * s);
308:     ctx.fillStyle = '#d4fdff';
309:     ctx.font = `700 ${19 * s}px "Rajdhani", sans-serif`;
310:     ctx.textAlign = 'center';
311:     ctx.save();
312:     ctx.translate(signX + 19 * s, signY + 50 * s);
313:     ctx.rotate(Math.PI / 2);
314:     ctx.fillText('BLADE', -32 * s, 6 * s);
315:     ctx.restore();
316:     ctx.restore();
317: 
318:     // magenta sign
319:     ctx.save();
320:     ctx.shadowColor = '#ff3d9e';
321:     ctx.shadowBlur = 20 * s;
322:     ctx.fillStyle = `rgba(255, 61, 158, ${0.26 * (0.75 + Math.sin(t * 3.1 + 2) * 0.1)})`;
323:     const s2x = w * 0.88 - (v.camX - 800) * s * 0.12;
324:     ctx.fillRect(s2x, horizon * 0.48, 26 * s, 88 * s);
325:     ctx.fillStyle = '#ffe0f1';
326:     ctx.font = `700 ${15 * s}px "Rajdhani", sans-serif`;
327:     ctx.fillText('09', s2x + 13 * s, horizon * 0.48 + 46 * s);
328:     ctx.restore();
329: 
330:     // rooftop floor
331:     const floor = ctx.createLinearGradient(0, gY, 0, h);
332:     floor.addColorStop(0, '#0c1126');
333:     floor.addColorStop(0.35, '#080b1a');
334:     floor.addColorStop(1, '#03040b');
335:     ctx.fillStyle = floor;
336:     ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);
337: 
338:     // glowing edge
339:     ctx.save();
340:     ctx.shadowColor = '#50e6ff';
341:     ctx.shadowBlur = 18 * s;
342:     ctx.strokeStyle = 'rgba(96, 234, 255, 0.9)';
343:     ctx.lineWidth = 2.5 * s;
344:     ctx.beginPath();
345:     ctx.moveTo(0, gY);
346:     ctx.lineTo(w, gY);
347:     ctx.stroke();
348:     ctx.restore();
349: 
350:     // floor perspective grid
351:     ctx.strokeStyle = 'rgba(70, 155, 220, 0.12)';
352:     ctx.lineWidth = 1;
353:     const vanish = w / 2 - (v.camX - 800) * s * 0.18;
354:     for (let i = 0; i < 12; i++) {
355:       const k = i / 12;
356:       const y = gY + Math.pow(k, 1.7) * (h - gY);
357:       ctx.beginPath();
358:       ctx.moveTo(0, y);
359:       ctx.lineTo(w, y);
360:       ctx.stroke();
361:     }
362:     for (let i = -9; i <= 9; i++) {
363:       ctx.beginPath();
364:       ctx.moveTo(vanish + i * 90 * s, gY);
365:       ctx.lineTo(vanish + i * 330 * s, h);
366:       ctx.stroke();
367:     }
368: 
369:     // magenta reflection streaks
370:     for (let i = 0; i < 5; i++) {
371:       const x = ((i * 0.23 + 0.08) * w + Math.sin(t * 0.2 + i) * 20 * s) - (v.camX - 800) * s * 0.25;
372:       const g = ctx.createLinearGradient(x, gY, x, h);
373:       g.addColorStop(0, 'rgba(255, 61, 158, 0.13)');
374:       g.addColorStop(0.6, 'rgba(255, 61, 158, 0.02)');
375:       g.addColorStop(1, 'rgba(255, 61, 158, 0)');
376:       ctx.fillStyle = g;
377:       ctx.fillRect(x, gY, 34 * s, h - gY);
378:     }
379: 
380:     // distant rooftop clutter
381:     this.rooftopUnits(ctx, v, t);
382:   }
