384:   rooftopUnits(ctx, v, t) {
385:     const s = v.scale, gY = v.groundY;
386:     const units = [
387:       { x: 0.06, w: 90, h: 45, glow: '#38cfe8' },
388:       { x: 0.91, w: 120, h: 58, glow: '#ff3d9e' },
389:     ];
390:     for (const u of units) {
391:       const x = u.x * v.w - (v.camX - 800) * s * 0.3;
392:       const w = u.w * s, h = u.h * s;
393:       ctx.fillStyle = '#0b1329';
394:       ctx.fillRect(x, gY - h, w, h);
395:       ctx.strokeStyle = 'rgba(90, 180, 230, 0.25)';
396:       ctx.lineWidth = 1;
397:       ctx.strokeRect(x, gY - h, w, h);
398:       ctx.fillStyle = 'rgba(80, 200, 235, 0.35)';
399:       ctx.fillRect(x + 6 * s, gY - h + 7 * s, w - 12 * s, 2 * s);
400:       ctx.fillStyle = u.glow;
401:       ctx.globalAlpha = 0.45 + Math.sin(t * 4 + x) * 0.15;
402:       ctx.fillRect(x + w * 0.7, gY - h + 12 * s, 3 * s, 3 * s);
403:       ctx.globalAlpha = 1;
404:     }
405:   }
