407:   drawFrost(ctx, t, v) {
408:     const { w, h } = v;
409:     const gY = v.groundY;
410:     const s = v.scale;
411:     const horizon = v.horizon;
412: 
413:     for (const st of stars) {
414:       const tw = 0.3 + Math.sin(t * 1.1 + st.p) * 0.25;
415:       ctx.globalAlpha = tw;
416:       ctx.fillStyle = '#d6f6ff';
417:       ctx.fillRect(st.x * w, st.y * horizon, st.s, st.s);
418:     }
419:     ctx.globalAlpha = 1;
420: 
421:     // aurora ribbons
422:     ctx.save();
423:     ctx.globalCompositeOperation = 'screen';
424:     for (let i = 0; i < 3; i++) {
425:       const yy = horizon * (0.2 + i * 0.09);
426:       const g = ctx.createLinearGradient(0, yy, w, yy + 80 * s);
427:       g.addColorStop(0, 'rgba(70, 255, 210, 0)');
428:       g.addColorStop(0.35, `rgba(${70 + i * 40}, 255, 210, ${0.08 + i * 0.025})`);
429:       g.addColorStop(0.6, `rgba(90, 150, 255, ${0.06 + i * 0.02})`);
430:       g.addColorStop(1, 'rgba(40, 80, 200, 0)');
431:       ctx.fillStyle = g;
432:       ctx.beginPath();
433:       ctx.moveTo(-40, yy);
434:       for (let x = -40; x <= w + 40; x += 60) {
435:         const y = yy + Math.sin(x * 0.006 + t * 0.4 + i * 1.8) * 22 * s + Math.sin(x * 0.013 + i) * 10 * s;
436:         ctx.lineTo(x, y);
437:       }
438:       for (let x = w + 40; x >= -40; x -= 60) {
439:         const y = yy + 70 * s + Math.sin(x * 0.005 + t * 0.3 + i * 1.2) * 26 * s;
440:         ctx.lineTo(x, y);
441:       }
442:       ctx.closePath();
443:       ctx.fill();
444:     }
445:     ctx.restore();
446: 
447:     // moon
448:     const mx = w * 0.73;
449:     const my = horizon * 0.27;
450:     const mr = 72 * s;
451:     const mg = ctx.createRadialGradient(mx, my, mr * 0.2, mx, my, mr * 3);
452:     mg.addColorStop(0, 'rgba(190, 245, 255, 0.30)');
453:     mg.addColorStop(0.3, 'rgba(130, 210, 255, 0.1)');
454:     mg.addColorStop(1, 'rgba(70, 130, 220, 0)');
455:     ctx.fillStyle = mg;
456:     ctx.beginPath();
457:     ctx.arc(mx, my, mr * 3, 0, TAU);
458:     ctx.fill();
459:     const moonG = ctx.createLinearGradient(mx, my - mr, mx, my + mr);
460:     moonG.addColorStop(0, '#ffffff');
461:     moonG.addColorStop(0.6, '#d9f4ff');
462:     moonG.addColorStop(1, '#9cc8e0');
463:     ctx.fillStyle = moonG;
464:     ctx.beginPath();
465:     ctx.arc(mx, my, mr, 0, TAU);
466:     ctx.fill();
467:     ctx.fillStyle = 'rgba(120, 160, 190, 0.14)';
468:     ctx.beginPath();
469:     ctx.arc(mx - mr * 0.28, my + mr * 0.12, mr * 0.3, 0, TAU);
470:     ctx.arc(mx + mr * 0.35, my - mr * 0.3, mr * 0.17, 0, TAU);
471:     ctx.fill();
472: 
473:     // mountain layers
474:     const mountains = [
475:       { base: horizon + 12 * s, h: 260, c1: '#091a2d', c2: '#0b2138', snow: 'rgba(160, 220, 245, 0.22)' },
476:       { base: horizon + 34 * s, h: 190, c1: '#0b2234', c2: '#102c42', snow: 'rgba(180, 235, 255, 0.3)' },
477:     ];
478:     for (let m = 0; m < mountains.length; m++) {
479:       const mt = mountains[m];
480:       const off = (v.camX - 800) * s * (0.15 + m * 0.1);
481:       ctx.beginPath();
482:       ctx.moveTo(-100, mt.base);
483:       const step = 140 * s;
484:       for (let x = -100; x <= w + 120; x += step) {
485:         const peak = mt.base - (mt.h * (0.55 + 0.45 * Math.sin((x + off) * 0.005 + m * 2.7))) * s;
486:         ctx.lineTo(x + step * 0.45, peak);
487:         ctx.lineTo(x + step, mt.base - 30 * s);
488:       }
489:       ctx.lineTo(w + 120, mt.base);
490:       ctx.closePath();
491:       const g = ctx.createLinearGradient(0, mt.base - mt.h * s, 0, mt.base);
492:       g.addColorStop(0, mt.c1);
493:       g.addColorStop(1, mt.c2);
494:       ctx.fillStyle = g;
495:       ctx.fill();
496:       // snow caps
497:       ctx.strokeStyle = mt.snow;
498:       ctx.lineWidth = 2 * s;
499:       ctx.beginPath();
500:       for (let x = -100; x <= w + 120; x += step) {
501:         const peak = mt.base - (mt.h * (0.55 + 0.45 * Math.sin((x + off) * 0.005 + m * 2.7))) * s;
502:         ctx.moveTo(x + step * 0.45, peak);
503:         ctx.lineTo(x + step * 0.32, peak + 28 * s);
504:         ctx.moveTo(x + step * 0.45, peak);
505:         ctx.lineTo(x + step * 0.58, peak + 24 * s);
506:       }
507:       ctx.stroke();
508:     }
509: 
510:     // pine forest
511:     const px = (x) => v.offX + x * s;
512:     for (let i = 0; i < 34; i++) {
513:       const x = px(-100 + i * 86 + Math.sin(i * 9.3) * 30);
514:       if (x < -80 || x > w + 80) continue;
515:       const ph = (90 + ((i * 37) % 110)) * s;
516:       const base = horizon + 20 * s;
517:       ctx.fillStyle = i % 3 === 0 ? '#071728' : '#0a1e32';
518:       ctx.beginPath();
519:       ctx.moveTo(x, base - ph);
520:       ctx.lineTo(x + 30 * s, base);
521:       ctx.lineTo(x - 30 * s, base);
522:       ctx.closePath();
523:       ctx.fill();
524:       ctx.beginPath();
525:       ctx.moveTo(x, base - ph * 0.68);
526:       ctx.lineTo(x + 38 * s, base + 2 * s);
527:       ctx.lineTo(x - 38 * s, base + 2 * s);
528:       ctx.closePath();
529:       ctx.fill();
530:       // snow on pine
531:       ctx.strokeStyle = 'rgba(200, 240, 255, 0.35)';
532:       ctx.lineWidth = 1.5 * s;
533:       ctx.beginPath();
534:       ctx.moveTo(x - 18 * s, base - ph * 0.22);
535:       ctx.lineTo(x, base - ph * 0.42);
536:       ctx.lineTo(x + 18 * s, base - ph * 0.22);
537:       ctx.stroke();
538:     }
539: 
540:     // torii gate
541:     this.drawTorii(ctx, v, t, w * 0.28, horizon + 26 * s, 1.15 * s);
542:     this.drawTorii(ctx, v, t, w * 0.82, horizon + 30 * s, 0.72 * s);
543: 
544:     // snow floor
545:     const floor = ctx.createLinearGradient(0, gY - 4 * s, 0, h);
546:     floor.addColorStop(0, '#b9dce8');
547:     floor.addColorStop(0.12, '#82aec5');
548:     floor.addColorStop(0.4, '#314f6b');
549:     floor.addColorStop(1, '#091a2d');
550:     ctx.fillStyle = floor;
551:     ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);
552: 
553:     // snow drift edge
554:     ctx.beginPath();
555:     ctx.moveTo(0, gY + 2 * s);
556:     for (let x = 0; x <= w; x += 40) {
557:       ctx.lineTo(x, gY + 2 * s + Math.sin(x * 0.03 + t * 0.2) * 2 * s);
558:     }
559:     ctx.lineTo(w, gY + 18 * s);
560:     ctx.lineTo(0, gY + 18 * s);
561:     ctx.closePath();
562:     ctx.fillStyle = 'rgba(226, 248, 255, 0.78)';
563:     ctx.fill();
564: 
565:     // stone tiles
566:     ctx.strokeStyle = 'rgba(180, 225, 245, 0.16)';
567:     ctx.lineWidth = 1.2;
568:     const vanish = w / 2 - (v.camX - 800) * s * 0.18;
569:     for (let i = 0; i < 9; i++) {
570:       const k = i / 9;
571:       const y = gY + 18 * s + Math.pow(k, 1.6) * (h - gY);
572:       ctx.beginPath();
573:       ctx.moveTo(0, y);
574:       ctx.lineTo(w, y);
575:       ctx.stroke();
576:     }
577:     for (let i = -8; i <= 8; i++) {
578:       ctx.beginPath();
579:       ctx.moveTo(vanish + i * 90 * s, gY + 18 * s);
580:       ctx.lineTo(vanish + i * 320 * s, h);
581:       ctx.stroke();
582:     }
583: 
584:     // ice sheen
585:     ctx.save();
586:     ctx.globalCompositeOperation = 'lighter';
587:     for (let i = 0; i < 4; i++) {
588:       const x = (0.15 + i * 0.24) * w + Math.sin(t * 0.3 + i) * 20;
589:       const g = ctx.createLinearGradient(x, gY, x, h);
590:       g.addColorStop(0, 'rgba(130, 230, 255, 0.14)');
591:       g.addColorStop(1, 'rgba(130, 230, 255, 0)');
592:       ctx.fillStyle = g;
593:       ctx.fillRect(x, gY, 22 * s, h - gY);
594:     }
595:     ctx.restore();
596:   }
