598:   drawTorii(ctx, v, t, x, baseY, scale) {
599:     const c1 = '#2a0d14', c2 = '#54121c';
600:     ctx.save();
601:     ctx.translate(x, baseY);
602:     ctx.scale(scale, scale);
603:     const g = ctx.createLinearGradient(0, -260, 0, 0);
604:     g.addColorStop(0, c2);
605:     g.addColorStop(1, c1);
606:     // pillars
607:     ctx.fillStyle = g;
608:     ctx.fillRect(-72, -220, 16, 220);
609:     ctx.fillRect(56, -220, 16, 220);
610:     // beams
611:     ctx.fillRect(-96, -232, 192, 13);
612:     ctx.fillRect(-82, -202, 164, 10);
613:     ctx.fillRect(-64, -180, 128, 7);
614:     // roof cap
615:     ctx.beginPath();
616:     ctx.moveTo(-120, -238);
617:     ctx.quadraticCurveTo(-20, -258, 0, -252);
618:     ctx.quadraticCurveTo(20, -258, 120, -238);
619:     ctx.lineTo(100, -248);
620:     ctx.quadraticCurveTo(0, -264, -100, -248);
621:     ctx.closePath();
622:     ctx.fillStyle = '#16070c';
623:     ctx.fill();
624:     // highlight
625:     ctx.strokeStyle = 'rgba(255, 120, 90, 0.25)';
626:     ctx.lineWidth = 1.2;
627:     ctx.strokeRect(-72, -220, 16, 220);
628:     ctx.strokeRect(56, -220, 16, 220);
629:     // lanterns
630:     for (const lx of [-92, 92]) {
631:       const glow = 0.5 + Math.sin(t * 2.2 + lx) * 0.15;
632:       ctx.save();
633:       ctx.shadowColor = '#ffb45c';
634:       ctx.shadowBlur = 18;
635:       ctx.fillStyle = `rgba(255, 180, 92, ${glow})`;
636:       ctx.beginPath();
637:       ctx.ellipse(lx, -180, 7, 10, 0, 0, TAU);
638:       ctx.fill();
639:       ctx.restore();
640:     }
641:     ctx.restore();
642:   }
