644:   drawFoundry(ctx, t, v) {
645:     const { w, h } = v;
646:     const gY = v.groundY;
647:     const s = v.scale;
648:     const horizon = v.horizon;
649: 
650:     // furnace glow
651:     const fg = ctx.createRadialGradient(w * 0.52, horizon + 20 * s, 10, w * 0.52, horizon + 20 * s, w * 0.6);
652:     fg.addColorStop(0, 'rgba(255, 128, 36, 0.34)');
653:     fg.addColorStop(0.35, 'rgba(190, 48, 18, 0.14)');
654:     fg.addColorStop(1, 'rgba(40, 5, 4, 0)');
655:     ctx.fillStyle = fg;
656:     ctx.fillRect(0, 0, w, h);
657: 
658:     // smoke haze
659:     for (let i = 0; i < 4; i++) {
660:       const y = horizon * (0.2 + i * 0.12);
661:       ctx.fillStyle = `rgba(70, 26, 22, ${0.05 + i * 0.015})`;
662:       ctx.beginPath();
663:       ctx.ellipse(w * (0.18 + i * 0.2) + Math.sin(t * 0.1 + i) * 40, y, w * 0.28, 40 * s, 0, 0, TAU);
664:       ctx.fill();
665:     }
666: 
667:     // chimneys / towers
668:     const structures = [
669:       { x: 0.08, w: 0.11, h: 340, c: '#160709' },
670:       { x: 0.23, w: 0.07, h: 260, c: '#1a080a' },
671:       { x: 0.69, w: 0.09, h: 300, c: '#190709' },
672:       { x: 0.86, w: 0.13, h: 370, c: '#140507' },
673:     ];
674:     for (let i = 0; i < structures.length; i++) {
675:       const st = structures[i];
676:       const x = st.x * w - (v.camX - 800) * s * 0.08;
677:       const sw = st.w * w;
678:       const sh = st.h * s;
679:       const g = ctx.createLinearGradient(x, horizon - sh, x, horizon);
680:       g.addColorStop(0, st.c);
681:       g.addColorStop(1, '#0b0406');
682:       ctx.fillStyle = g;
683:       ctx.fillRect(x, horizon - sh, sw, sh + 8 * s);
684:       // bands
685:       ctx.strokeStyle = 'rgba(255, 100, 40, 0.10)';
686:       ctx.lineWidth = 2 * s;
687:       for (let k = 1; k < 6; k++) {
688:         ctx.beginPath();
689:         ctx.moveTo(x, horizon - sh + (k / 6) * sh);
690:         ctx.lineTo(x + sw, horizon - sh + (k / 6) * sh);
691:         ctx.stroke();
692:       }
693:       // top light
694:       ctx.save();
695:       ctx.shadowColor = '#ff5a1e';
696:       ctx.shadowBlur = 20 * s;
697:       ctx.fillStyle = `rgba(255, 74, 20, ${0.55 + Math.sin(t * 2 + i) * 0.2})`;
698:       ctx.fillRect(x + sw * 0.5 - 3 * s, horizon - sh - 4 * s, 6 * s, 6 * s);
699:       ctx.restore();
700:       // smoke from chimney
701:       if (i % 2 === 0) {
702:         for (let k = 0; k < 4; k++) {
703:           const age = ((t * 0.07 + k * 0.23 + i * 0.2) % 1);
704:           const yy = horizon - sh - 10 * s - age * 160 * s;
705:           const xx = x + sw * 0.5 + Math.sin(age * 4 + i) * 34 * s;
706:           ctx.globalAlpha = (1 - age) * 0.18;
707:           ctx.fillStyle = '#1a0b0b';
708:           ctx.beginPath();
709:           ctx.arc(xx, yy, (12 + age * 30) * s, 0, TAU);
710:           ctx.fill();
711:         }
712:         ctx.globalAlpha = 1;
713:       }
714:     }
715: 
716:     // pipe network
717:     ctx.strokeStyle = 'rgba(60, 20, 20, 0.9)';
718:     ctx.lineWidth = 10 * s;
719:     ctx.beginPath();
720:     ctx.moveTo(-40, horizon - 90 * s);
721:     ctx.lineTo(w * 0.36, horizon - 110 * s);
722:     ctx.lineTo(w * 0.36, horizon - 30 * s);
723:     ctx.moveTo(w * 0.64, horizon - 70 * s);
724:     ctx.lineTo(w + 40, horizon - 120 * s);
725:     ctx.stroke();
726:     ctx.strokeStyle = 'rgba(255, 88, 30, 0.25)';
727:     ctx.lineWidth = 2 * s;
728:     ctx.beginPath();
729:     ctx.moveTo(-40, horizon - 95 * s);
730:     ctx.lineTo(w * 0.36, horizon - 115 * s);
731:     ctx.stroke();
732: 
733:     // cranes
734:     ctx.strokeStyle = 'rgba(40, 12, 12, 0.95)';
735:     ctx.lineWidth = 6 * s;
736:     ctx.beginPath();
737:     ctx.moveTo(w * 0.5, horizon);
738:     ctx.lineTo(w * 0.5, horizon - 220 * s);
739:     ctx.lineTo(w * 0.7, horizon - 160 * s);
740:     ctx.moveTo(w * 0.5, horizon - 220 * s);
741:     ctx.lineTo(w * 0.44, horizon - 190 * s);
742:     ctx.stroke();
743: 
744:     // furnace mouth
745:     const fx = w * 0.5;
746:     const fy = horizon - 30 * s;
747:     ctx.save();
748:     ctx.shadowColor = '#ff6a1e';
749:     ctx.shadowBlur = 40 * s;
750:     ctx.fillStyle = `rgba(255, 104, 24, ${0.7 + Math.sin(t * 3) * 0.1})`;
751:     ctx.beginPath();
752:     ctx.arc(fx, fy, 54 * s, 0, TAU);
753:     ctx.fill();
754:     ctx.fillStyle = 'rgba(255, 220, 140, 0.85)';
755:     ctx.beginPath();
756:     ctx.arc(fx, fy, 28 * s, 0, TAU);
757:     ctx.fill();
758:     ctx.restore();
759:     // furnace arch
760:     ctx.strokeStyle = '#250809';
761:     ctx.lineWidth = 14 * s;
762:     ctx.beginPath();
763:     ctx.arc(fx, fy, 66 * s, Math.PI, TAU);
764:     ctx.stroke();
765:     ctx.strokeStyle = 'rgba(255, 100, 30, 0.3)';
766:     ctx.lineWidth = 2 * s;
767:     ctx.beginPath();
768:     ctx.arc(fx, fy, 66 * s, Math.PI, TAU);
769:     ctx.stroke();
770: 
771:     // metal floor
772:     const floor = ctx.createLinearGradient(0, gY - 2 * s, 0, h);
773:     floor.addColorStop(0, '#2a1110');
774:     floor.addColorStop(0.15, '#180a0b');
775:     floor.addColorStop(0.6, '#0d0507');
776:     floor.addColorStop(1, '#050203');
777:     ctx.fillStyle = floor;
778:     ctx.fillRect(0, gY - 2 * s, w, h - gY + 2 * s);
779: 
780:     // hot edge
781:     ctx.save();
782:     ctx.shadowColor = '#ff6a1e';
783:     ctx.shadowBlur = 22 * s;
784:     ctx.strokeStyle = 'rgba(255, 118, 40, 0.9)';
785:     ctx.lineWidth = 2.5 * s;
786:     ctx.beginPath();
787:     ctx.moveTo(0, gY);
788:     ctx.lineTo(w, gY);
789:     ctx.stroke();
790:     ctx.restore();
791: 
792:     // grate lines
793:     ctx.strokeStyle = 'rgba(150, 60, 30, 0.15)';
794:     ctx.lineWidth = 1;
795:     for (let i = 0; i < 11; i++) {
796:       const k = i / 11;
797:       const y = gY + Math.pow(k, 1.6) * (h - gY);
798:       ctx.beginPath();
799:       ctx.moveTo(0, y);
800:       ctx.lineTo(w, y);
801:       ctx.stroke();
802:     }
803:     const vanish = w / 2 - (v.camX - 800) * s * 0.18;
804:     for (let i = -9; i <= 9; i++) {
805:       ctx.beginPath();
806:       ctx.moveTo(vanish + i * 90 * s, gY);
807:       ctx.lineTo(vanish + i * 340 * s, h);
808:       ctx.stroke();
809:     }
810: 
811:     // magma cracks
812:     ctx.save();
813:     ctx.globalCompositeOperation = 'lighter';
814:     for (let i = 0; i < 7; i++) {
815:       const bx = ((i * 0.17 + 0.05) * w + Math.sin(t * 0.2 + i) * 16 * s) - (v.camX - 800) * s * 0.2;
816:       const by = gY + (0.2 + (i % 3) * 0.22) * (h - gY);
817:       const len = (40 + (i % 4) * 32) * s;
818:       ctx.strokeStyle = `rgba(255, 86, 20, ${0.22 + (i % 3) * 0.06})`;
819:       ctx.lineWidth = (2 + (i % 2)) * s;
820:       ctx.beginPath();
821:       ctx.moveTo(bx, by);
822:       ctx.lineTo(bx + len * 0.5, by - 4 * s);
823:       ctx.lineTo(bx + len, by + 3 * s);
824:       ctx.stroke();
825:     }
826:     ctx.restore();
827:   }
