829:   drawArenaParticles(ctx, arena, t, v) {
830:     const { w, h } = v;
831:     const gY = v.groundY;
832:     if (arena.key === 'neon') {
833:       this.drawRain(ctx, t, v);
834:       // floating holographic dust
835:       for (const d of dust) {
836:         const x = ((d.x + t * d.sp) % 1) * w;
837:         const y = gY - ((d.y * 500 + Math.sin(t * 0.6 + d.sway) * 30) * v.scale) - 60 * v.scale;
838:         ctx.globalAlpha = d.a;
839:         ctx.fillStyle = '#55e6ff';
840:         ctx.beginPath();
841:         ctx.arc(x, y, d.r * v.scale, 0, TAU);
842:         ctx.fill();
843:       }
844:       ctx.globalAlpha = 1;
845:     } else if (arena.key === 'frost') {
846:       this.drawSnow(ctx, t, v);
847:     } else {
848:       this.drawEmbers(ctx, t, v);
849:     }
850:   }
851: 
852:   drawRain(ctx, t, v) {
853:     const { w, h } = v;
854:     ctx.save();
855:     ctx.lineCap = 'round';
856:     for (const r of rain) {
857:       const x = ((r.x + t * 0.008) % 1) * w;
858:       const y = (((r.y + t * r.sp * 0.06) % 1)) * h;
859:       ctx.strokeStyle = `rgba(150, 220, 255, ${r.a})`;
860:       ctx.lineWidth = 1;
861:       ctx.beginPath();
862:       ctx.moveTo(x, y);
863:       ctx.lineTo(x - r.len * 0.15, y + r.len);
864:       ctx.stroke();
865:     }
866:     ctx.restore();
867:   }
868: 
869:   drawSnow(ctx, t, v) {
870:     const { w, h } = v;
871:     for (const s of snow) {
872:       const x = ((s.x + Math.sin(t * 0.4 + s.sway) * 0.03 + t * 0.004) % 1) * w;
873:       const y = ((s.y + t * s.sp * 6) % 1) * h;
874:       ctx.globalAlpha = s.a;
875:       ctx.fillStyle = '#e9fbff';
876:       ctx.beginPath();
877:       ctx.arc(x, y, s.r * v.scale * 0.9, 0, TAU);
878:       ctx.fill();
879:     }
880:     ctx.globalAlpha = 1;
881:   }
882: 
883:   drawEmbers(ctx, t, v) {
884:     const { w, h } = v;
885:     for (const e of embers) {
886:       const x = ((e.x + Math.sin(t * 0.5 + e.sway) * 0.02 + t * 0.005) % 1) * w;
887:       const y = h - ((e.y + t * e.sp * 4) % 1) * (h - v.horizon * 0.4);
888:       ctx.globalAlpha = e.a * (0.6 + Math.sin(t * 3 + e.sway) * 0.4);
889:       ctx.fillStyle = Math.sin(e.sway) > 0 ? '#ff8a3c' : '#ffc25c';
890:       ctx.beginPath();
891:       ctx.arc(x, y, e.r * v.scale * 0.8, 0, TAU);
892:       ctx.fill();
893:     }
894:     ctx.globalAlpha = 1;
895:   }
