897:   drawForeground(ctx, arena, t, v, scene) {
898:     const { w, h } = v;
899:     // bottom vignette fog
900:     const g = ctx.createLinearGradient(0, h * 0.72, 0, h);
901:     g.addColorStop(0, 'rgba(0,0,0,0)');
902:     g.addColorStop(1, 'rgba(0,0,0,0.42)');
903:     ctx.fillStyle = g;
904:     ctx.fillRect(0, h * 0.72, w, h * 0.28);
905: 
906:     if (arena.key === 'neon') {
907:       // foreground rain spatter
908:       ctx.save();
909:       ctx.globalCompositeOperation = 'lighter';
910:       for (let i = 0; i < 12; i++) {
911:         const age = (t * 0.4 + i / 12) % 1;
912:         const x = ((i * 0.137 + 0.02) * w + Math.sin(t * 0.3 + i) * 8) % w;
913:         const y = v.groundY + age * (h - v.groundY) * 1.1;
914:         ctx.fillStyle = `rgba(90, 225, 255, ${(1 - age) * 0.14})`;
915:         ctx.beginPath();
916:         ctx.ellipse(x, y, 18 * v.scale * (0.3 + age), 2.5 * v.scale, 0, 0, TAU);
917:         ctx.fill();
918:       }
919:       ctx.restore();
920:     } else if (arena.key === 'frost') {
921:       // drifting foreground flakes
922:       for (let i = 0; i < 18; i++) {
923:         const x = ((i * 0.071 + t * 0.01) % 1) * w;
924:         const y = ((i * 0.043 + t * 0.03) % 1) * h;
925:         ctx.globalAlpha = 0.16;
926:         ctx.fillStyle = '#eaffff';
927:         ctx.beginPath();
928:         ctx.arc(x, y, (1.2 + (i % 3)) * v.scale * 1.5, 0, TAU);
929:         ctx.fill();
930:       }
931:       ctx.globalAlpha = 1;
932:     } else {
933:       // foreground embers / heat dust
934:       ctx.save();
935:       ctx.globalCompositeOperation = 'lighter';
936:       for (let i = 0; i < 14; i++) {
937:         const x = ((i * 0.09 + 0.02 + Math.sin(t * 0.6 + i) * 0.02) % 1) * w;
938:         const y = h - ((i * 0.12 + t * 0.04) % 1) * h * 0.7;
939:         ctx.fillStyle = `rgba(255, 122, 42, ${0.08 + (i % 3) * 0.04})`;
940:         ctx.beginPath();
941:         ctx.arc(x, y, (1.5 + (i % 4)) * v.scale, 0, TAU);
942:         ctx.fill();
943:       }
944:       ctx.restore();
945:     }
946:   }
