948:   drawParticles(ctx, parts, t) {
949:     if (!parts.length) return;
950:     ctx.save();
951:     for (const p of parts) {
952:       const k = p.life / p.maxLife;
953:       if (k <= 0) continue;
954:       ctx.globalAlpha = clamp(k, 0, 1) * (p.alpha ?? 1);
955:       if (p.additive) ctx.globalCompositeOperation = 'lighter';
956:       else ctx.globalCompositeOperation = 'source-over';
957:       ctx.fillStyle = p.color;
958:       if (p.shape === 'line') {
959:         ctx.strokeStyle = p.color;
960:         ctx.lineWidth = p.size;
961:         ctx.lineCap = 'round';
962:         ctx.beginPath();
963:         ctx.moveTo(p.x, p.y);
964:         ctx.lineTo(p.x - p.vx * 0.02, p.y - p.vy * 0.02);
965:         ctx.stroke();
966:       } else if (p.shape === 'shard') {
967:         ctx.save();
968:         ctx.translate(p.x, p.y);
969:         ctx.rotate(p.rot || 0);
970:         ctx.beginPath();
971:         ctx.moveTo(0, -p.size);
972:         ctx.lineTo(p.size * 0.5, 0);
973:         ctx.lineTo(0, p.size);
974:         ctx.lineTo(-p.size * 0.5, 0);
975:         ctx.closePath();
976:         ctx.fill();
977:         ctx.restore();
978:       } else {
979:         ctx.beginPath();
980:         ctx.arc(p.x, p.y, p.size * (0.4 + k * 0.6), 0, TAU);
981:         ctx.fill();
982:       }
983:     }
984:     ctx.restore();
985:   }
