987:   drawProjectiles(ctx, projectiles, t) {
988:     for (const p of projectiles) {
989:       ctx.save();
990:       ctx.translate(p.x, p.y);
991:       ctx.scale(p.facing, 1);
992:       ctx.globalCompositeOperation = 'lighter';
993:       if (p.type === 'ice') {
994:         const r = p.radius;
995:         // aura
996:         const g = ctx.createRadialGradient(0, 0, 4, 0, 0, r * 2.6);
997:         g.addColorStop(0, 'rgba(255,255,255,0.95)');
998:         g.addColorStop(0.18, 'rgba(130,245,255,0.75)');
999:         g.addColorStop(0.5, 'rgba(50,180,255,0.24)');
1000:         g.addColorStop(1, 'rgba(20,80,220,0)');
1001:         ctx.fillStyle = g;
1002:         ctx.beginPath();
1003:         ctx.arc(0, 0, r * 2.6, 0, TAU);
1004:         ctx.fill();
1005:         // rotating crescent blades
1006:         for (let i = 0; i < 3; i++) {
1007:           const rot = t * 8 + i * (TAU / 3);
1008:           ctx.save();
1009:           ctx.rotate(rot);
1010:           ctx.strokeStyle = i === 0 ? 'rgba(255,255,255,0.95)' : 'rgba(120,240,255,0.8)';
1011:           ctx.lineWidth = 4 - i * 0.8;
1012:           ctx.beginPath();
1013:           ctx.arc(0, 0, r * (0.85 + i * 0.14), -1.15, 1.15);
1014:           ctx.stroke();
1015:           ctx.restore();
1016:         }
1017:         // core
1018:         ctx.fillStyle = 'rgba(255,255,255,0.95)';
1019:         ctx.beginPath();
1020:         ctx.ellipse(0, 0, r * 0.42, r * 0.22, 0, 0, TAU);
1021:         ctx.fill();
1022:         // trailing spikes
1023:         ctx.strokeStyle = 'rgba(160, 245, 255, 0.7)';
1024:         ctx.lineWidth = 2.4;
1025:         for (let i = 0; i < 6; i++) {
1026:           const a = (i / 6) * TAU;
1027:           const len = r * (1.3 + Math.sin(t * 14 + i) * 0.2);
1028:           ctx.beginPath();
1029:           ctx.moveTo(Math.cos(a) * r * 0.5, Math.sin(a) * r * 0.5);
1030:           ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
1031:           ctx.stroke();
1032:         }
1033:       } else {
1034:         const r = p.radius;
1035:         const g = ctx.createRadialGradient(0, 0, 4, 0, 0, r * 2.8);
1036:         g.addColorStop(0, 'rgba(255,255,240,0.95)');
1037:         g.addColorStop(0.18, 'rgba(255,200,90,0.8)');
1038:         g.addColorStop(0.46, 'rgba(255,80,25,0.34)');
1039:         g.addColorStop(1, 'rgba(255,30,0,0)');
1040:         ctx.fillStyle = g;
1041:         ctx.beginPath();
1042:         ctx.arc(0, 0, r * 2.7, 0, TAU);
1043:         ctx.fill();
1044:         // jagged fire ring
1045:         ctx.rotate(t * 3);
1046:         ctx.fillStyle = 'rgba(255, 120, 30, 0.72)';
1047:         ctx.beginPath();
1048:         for (let i = 0; i < 12; i++) {
1049:           const a = (i / 12) * TAU;
1050:           const rr = i % 2 === 0 ? r * 1.12 : r * 0.7;
1051:           ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
1052:         }
1053:         ctx.closePath();
1054:         ctx.fill();
1055:         ctx.fillStyle = 'rgba(255, 236, 170, 0.92)';
1056:         ctx.beginPath();
1057:         ctx.arc(0, 0, r * 0.46, 0, TAU);
1058:         ctx.fill();
1059:         // flame tongues
1060:         ctx.strokeStyle = 'rgba(255, 140, 40, 0.65)';
1061:         ctx.lineWidth = 3;
1062:         for (let i = 0; i < 8; i++) {
1063:           const a = (i / 8) * TAU + t * 2;
1064:           const len = r * (1.5 + Math.sin(t * 12 + i * 2) * 0.3);
1065:           ctx.beginPath();
1066:           ctx.moveTo(Math.cos(a) * r * 0.7, Math.sin(a) * r * 0.7);
1067:           ctx.quadraticCurveTo(
1068:             Math.cos(a + 0.3) * len, Math.sin(a + 0.3) * len,
1069:             Math.cos(a) * len * 1.2, Math.sin(a) * len * 1.2
1070:           );
1071:           ctx.stroke();
1072:         }
1073:       }
1074:       ctx.restore();
1075:     }
1076:   }
