1078:   drawEffects(ctx, effects, t) {
1079:     for (const e of effects) {
1080:       const k = clamp(e.life / e.maxLife, 0, 1);
1081:       ctx.save();
1082:       if (e.type === 'hit') {
1083:         ctx.translate(e.x, e.y);
1084:         ctx.globalCompositeOperation = 'lighter';
1085:         ctx.globalAlpha = k;
1086:         const size = e.size * (0.6 + (1 - k) * 0.9);
1087:         const g = ctx.createRadialGradient(0, 0, 1, 0, 0, size * 2);
1088:         g.addColorStop(0, '#ffffff');
1089:         g.addColorStop(0.25, e.color || '#9ff6ff');
1090:         g.addColorStop(1, 'rgba(0,0,0,0)');
1091:         ctx.fillStyle = g;
1092:         ctx.beginPath();
1093:         ctx.arc(0, 0, size * 2, 0, TAU);
1094:         ctx.fill();
1095:         ctx.strokeStyle = '#ffffff';
1096:         ctx.lineWidth = 2.5 * k;
1097:         for (let i = 0; i < 8; i++) {
1098:           const a = (i / 8) * TAU + (e.seed || 0);
1099:           const len = size * (1.4 + (i % 2) * 0.7);
1100:           ctx.beginPath();
1101:           ctx.moveTo(Math.cos(a) * size * 0.3, Math.sin(a) * size * 0.3);
1102:           ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
1103:           ctx.stroke();
1104:         }
1105:       } else if (e.type === 'block') {
1106:         ctx.translate(e.x, e.y);
1107:         ctx.globalCompositeOperation = 'lighter';
1108:         ctx.globalAlpha = k * 0.9;
1109:         ctx.strokeStyle = e.color || '#9feaff';
1110:         ctx.lineWidth = 5 * k;
1111:         ctx.beginPath();
1112:         ctx.arc(0, 0, e.size * (1.2 - k * 0.5), -1.2, 1.2);
1113:         ctx.stroke();
1114:         ctx.lineWidth = 2 * k;
1115:         ctx.beginPath();
1116:         ctx.arc(0, 0, e.size * (0.8 - k * 0.3), -1.3, 1.3);
1117:         ctx.stroke();
1118:         for (let i = 0; i < 6; i++) {
1119:           const a = -1.2 + (i / 5) * 2.4;
1120:           const len = e.size * (0.5 + (1 - k) * 0.9);
1121:           ctx.beginPath();
1122:           ctx.moveTo(Math.cos(a) * e.size * 0.4, Math.sin(a) * e.size * 0.4);
1123:           ctx.lineTo(Math.cos(a) * len, Math.sin(a) * len);
1124:           ctx.stroke();
1125:         }
1126:       } else if (e.type === 'ring') {
1127:         ctx.translate(e.x, e.y);
1128:         ctx.globalCompositeOperation = 'lighter';
1129:         ctx.globalAlpha = k * (e.alpha || 0.7);
1130:         ctx.strokeStyle = e.color || '#9ff6ff';
1131:         ctx.lineWidth = (e.width || 5) * k;
1132:         ctx.beginPath();
1133:         ctx.ellipse(0, 0, e.size * (1.2 - k), e.size * 0.3 * (1.2 - k), 0, 0, TAU);
1134:         ctx.stroke();
1135:       } else if (e.type === 'slash') {
1136:         ctx.translate(e.x, e.y);
1137:         ctx.scale(e.facing || 1, 1);
1138:         ctx.globalCompositeOperation = 'lighter';
1139:         ctx.globalAlpha = k;
1140:         const p = 1 - k;
1141:         const a0 = e.angle0 ?? -1.5;
1142:         const a1 = e.angle1 ?? 0.9;
1143:         const r = e.size || 140;
1144:         const grad = ctx.createLinearGradient(-r, -r, r, r);
1145:         grad.addColorStop(0, 'rgba(255,255,255,0)');
1146:         grad.addColorStop(0.3, e.color || '#bffaff');
1147:         grad.addColorStop(0.7, '#ffffff');
1148:         grad.addColorStop(1, 'rgba(255,255,255,0)');
1149:         ctx.strokeStyle = grad;
1150:         ctx.lineWidth = (e.width || 16) * (0.4 + k * 0.8);
1151:         ctx.lineCap = 'round';
1152:         ctx.beginPath();
1153:         ctx.arc(0, 0, r * (e.radius || 1) * (0.8 + p * 0.35), a0 + p * 0.5, a1 + p * 0.2);
1154:         ctx.stroke();
1155:         ctx.lineWidth = Math.max(1, (e.width || 16) * 0.22 * k);
