import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const variants = [
  ['headless-default', { headless: true }],
  ['headless-nogpu', { headless: true, args: ['--disable-gpu'] }],
  ['headless-angle-swift', { headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--disable-gpu-sandbox'] }],
  ['headed-nogpu', { headless: false, args: ['--disable-gpu'] }],
  ['headed-default', { headless: false, args: [] }],
];
for (const [name, opts] of variants) {
  let browser;
  try {
    browser = await chromium.launch({ ...config.browser.launchOptions, ...opts, timeout: 30000 });
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    await page.goto('http://localhost:3002', { waitUntil: 'load' });
    await page.waitForTimeout(1000);
    await page.evaluate(() => { window.__frames=0; const t=()=>{window.__frames++;requestAnimationFrame(t);};requestAnimationFrame(t); });
    await page.waitForTimeout(2000);
    const f = await page.evaluate(()=>window.__frames);
    console.log(name, f, (f/2).toFixed(1)+'fps');
  } catch (e) { console.log(name, 'ERR', e.message.split('\n')[0]); }
  finally { if (browser) await browser.close(); }
}
EOF
