const wait = (ms) => page.waitForTimeout(ms);
const state = () => page.evaluate(() => {
  const b = window.__blade; const g = b.game;
  return {
    scene: b.app.scene, paused: b.app.paused,
    phase: g && g.phase, timer: g && +g.timer.toFixed(1),
    round: g && g.round, pw: g && g.player.roundWins, cw: g && g.cpu.roundWins,
    px: g && +g.player.x.toFixed(0), cx: g && +g.cpu.x.toFixed(0),
    php: g && +g.player.hp.toFixed(0), chp: g && +g.cpu.hp.toFixed(0),
    pE: g && +g.player.energy.toFixed(0), cE: g && +g.cpu.energy.toFixed(0),
    pstate: g && g.player.state, cstate: g && g.cpu.state,
    pattack: g && g.player.attack && g.player.attack.key,
    cattack: g && g.cpu.attack && g.cpu.attack.key,
    pcombo: g && g.player.combo, ccombo: g && g.cpu.combo,
    proj: g && g.projectiles.length,
    pblock: g && g.player.blocking,
    hudTimer: document.getElementById('timer').textContent,
    matchActive: document.getElementById('screen-match').classList.contains('is-active'),
    pauseActive: document.getElementById('screen-pause').classList.contains('is-active'),
    touchVisible: !document.getElementById('touch-controls').classList.contains('is-hidden'),
    isTouch: document.body.classList.contains('is-touch'),
  };
});
const log = async (label) => console.log(label, JSON.stringify(await state()));

async function enterFight({ fighter = 'raze', arena = 2 } = {}) {
  await page.click('#btn-start');
  await wait(350);
  await page.click(`[data-fighter="${fighter}"]`);
  await wait(200);
  await page.click(`[data-arena="${arena}"]`);
