await page.waitForTimeout(800);
const m = await page.evaluate(() => {
  const q = (s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), h: Math.round(r.height), w: Math.round(r.width), scrollH: e.scrollHeight, clientH: e.clientHeight }; };
  return { body: q('body'), screen: q('#screen-select'), bodyEl: q('.select-body'), head: q('.select-header'), header: q('.arena-head'), grid: q('.arena-grid'), footer: q('.select-footer'), innerH: innerHeight, scrollY: document.querySelector('.select-body')?.scrollTop, docH: document.documentElement.scrollHeight };
});
console.log(JSON.stringify(m, null, 2));
await page.screenshot({ path: join(out, 'm-select.png'), fullPage: false });
// scroll the select body to bottom if scrollable
await page.evaluate(() => { const b = document.querySelector('.select-body'); if (b) b.scrollTop = b.scrollHeight; });
await page.waitForTimeout(300);
await page.screenshot({ path: join(out, 'm-select-bottom.png') });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

