import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, args: [], timeout: 30000 });

for (const [name, vp] of [['m-portrait', { width: 390, height: 844 }], ['m-landscape', { width: 844, height: 390 }]]) {
  const page = await browser.newPage({ viewport: vp, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); console.log(name, 'PAGEERROR', e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.click('#btn-start');
  await page.waitForTimeout(300);
  await page.click('[data-arena="2"]');
  await page.waitForTimeout(200);
  await page.click('#btn-fight');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: join(out, name + '-ember.png') });
  const info = await page.evaluate(() => {
    const v = window.__blade.renderer.view;
    return { scale: v.scale, mobile: v.mobile, gY: Math.round(v.groundY), horizon: Math.round(v.horizon), touch: !document.getElementById('touch-controls').classList.contains('is-hidden') };
  });
  console.log(name, JSON.stringify(info), JSON.stringify(errors));
  await page.close();
}
await browser.close();

