import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, args: [], timeout: 30000 });
for (const [name, vp] of [['se-select', { width: 375, height: 667 }], ['laptop-select', { width: 1366, height: 768 }]]) {
  const page = await browser.newPage({ viewport: vp, deviceScaleFactor: name.startsWith('se') ? 2 : 1, isMobile: name.startsWith('se'), hasTouch: name.startsWith('se') });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log(name, 'PAGEERROR', e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.click('#btn-start');
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(out, name + '.png') });
  const m = await page.evaluate(() => {
    const s = document.getElementById('screen-select');
    const f = document.querySelector('.select-footer');
    const g = document.querySelector('.arena-grid');
    const gr = g.getBoundingClientRect();
    const fr = f.getBoundingClientRect();
    return { screenScrollH: s.scrollHeight, screenClientH: s.clientHeight, scrollTop: s.scrollTop, gridBottom: Math.round(gr.bottom), footerBottom: Math.round(fr.bottom), footerTop: Math.round(fr.top), innerH: innerHeight, docH: document.documentElement.scrollHeight };
  });
  console.log(name, JSON.stringify(m), 'errors', JSON.stringify(errors));
  // scroll to footer and capture
  await page.evaluate(() => { const s = document.getElementById('screen-select'); s.scrollTop = s.scrollHeight; });
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(out, name + '-bottom.png') });
  await page.close();
}
await browser.close();

