import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, args: [], timeout: 30000 });
const names = ['neon', 'frost', 'ember'];

for (let i = 0; i < 3; i++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log(names[i], 'PAGEERROR', e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.click('#btn-start');
  await page.waitForTimeout(350);
  await page.click(`[data-arena="${i}"]`);
  await page.waitForTimeout(250);
  await page.click('#btn-fight');
  await page.waitForFunction(() => window.__blade.game && window.__blade.game.phase === 'active', null, { timeout: 12000 });
  await page.evaluate(() => {
    const g = window.__blade.game;
    g.ai.update = () => {};
    g.player.x = 540; g.cpu.x = 930; g.player.facing = 1; g.cpu.facing = -1;
    g.player.vx = 0; g.cpu.vx = 0; g.cpu.state = 'idle'; g.cpu.hitstun = 0;
    g.player.energy = 100; g.cpu.hp = g.cpu.maxHp;
    g.projectiles.length = 0;
  });
  await page.waitForTimeout(300);
  await page.keyboard.press('Space');
  await page.waitForTimeout(210);
  await page.screenshot({ path: join(out, `final-${names[i]}-special.png`) });
  console.log(names[i], 'errors', JSON.stringify(errors));
  await page.close();
}
await browser.close();
